(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-batch-invariant-rollout"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-1\">一 · 事故现场：同一 prompt，两个概率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-2\">二 · 问题的精确表述：归约顺序是批的函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-3\">三 · 机制：把归约顺序从批里摘出来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-4\">四 · 适用边界：什么时候值得付这个代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-5\">五 · 一个具体例子：从事故到配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-6\">六 · 批不变采样解决的是“概率不可复现”，不是“策略不稳”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-7\">七 · 内核配置装载：把“批无关”钉进启动参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-8\">八 · 组批与 token 入队：调度器卸下数值包袱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-9\">九 · Decode step 的 attention 归约：固定分块的 max 与 sum</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-10\">十 · lm_head 与 softmax 的 logprob 路径：确定性 reduce 树</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-11\">十一 · 训练侧重算与不一致回退：阈值判定与高精度路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-12\">十二 · 流水线适配与吞吐账：TMA、warp-specialized 与量化路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-13\">十三 · 批不变内核的失效边界与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-14\">十四 · 把“批不变”写成一条可证明的误差界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-15\">十五 · 核心公式的第二形式：归约树与 batch 的正交性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-16\">十六 · 伪代码：从 kernel 配置到 logprob 落盘</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-17\">十七 · 与 NVFP4、TMA 的适配：确定性必须穿透量化路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-18\">十八 · 批调度器的解放与它的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-19\">十九 · 批不变内核的失效边界与吞吐账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-20\">二十 · 请求形态：批量 decode 是唯一甜点区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-21\">二十一 · 长度分布：短中序列是主战场，长尾要隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-22\">二十二 · 并发与批大小：动态批是卖点，也是压力源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-23\">二十三 · 负载不对时：三种可观测的失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-24\">二十四 · 配方落地：把负载约束写进调度器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-25\">二十五 · 负载配方与失效边界：批不变内核在什么请求形态下才划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-26\">二十六 · 硬件档位：先定确定性预算，再定算力档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-27\">二十七 · 并行拓扑：确定性归约的域边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-28\">二十八 · 量化方案：NVFP4 路径的确定性前置条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-29\">二十九 · KV 策略：分片规则与 batch 解耦</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-30\">三十 · 调度参数：把确定性成本关进吞吐预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-31\">三十一 · 可复现配置思路：从内核版本到验收口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-32\">三十二 · 批不变内核的部署边界：什么时候值得为确定性付这笔账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-33\">三十三 · 固定归约在SM100上的真实开销：并行度换确定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-34\">三十四 · 显存与KV带宽：确定性路径不改变容量，但改变访问节律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-35\">三十五 · 通信：确定性kernel与集合通信的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-36\">三十六 · 尾延迟：固定分块在batch收缩时的刚性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-37\">三十七 · 规模上去以后哪里先崩：四条曲线的交叉点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-38\">三十八 · 确定性内核的吞吐税：固定 split-K 与 TMA 流水线的冲突点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-39\">三十九 · NVFP4 路径上的确定性缺口与逐位一致的脆弱前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-40\">四十 · 精度漂移的三种来源与可观测判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-41\">四十一 · OOM 的三条隐蔽通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-42\">四十二 · 批抖动与路由不均的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-43\">四十三 · 尾延迟尖刺的定位顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-44\">四十四 · 回滚的分级与版本对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-45\">四十五 · 批不变内核的失效面：从逐位一致到逐位漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-46\">四十六 · 对照的坐标系：误差来源决定算法归属</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-47\">四十七 · 决策表：五个维度的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-48\">四十八 · 与量化路径的共存条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-49\">四十九 · 与异步流水线的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-50\">五十 · 适用条件与规模上限的判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-batch-invariant-rollout-sec-51\">五十一 · 选型边界：批不变内核与量化稳定、异步同步、stock 内核的分工</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:525px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 525.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">将attention与GEMM的归约按固定分块大小切分，跨块累加顺序与ba…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对softmax与layernorm使用确定性归约树，禁用批相关的spli…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">rollout采样记录token与对应logprob，训练侧用同一确定性k…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对不一致样本按阈值标记并回退到高精度路径重算</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"443.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批调度器在组批时不再需要为数值一致性做特殊排序，可自由追求吞吐</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-batch-invariant-rollout-sec-1\">一 · 事故现场：同一 prompt，两个概率</h3>\n<p>某 RL 训练任务在 GB200 NVL72 上跑 GRPO，rollout 引擎与训练侧共享同一份权重。事故的表征很朴素：同一个 prompt 的同一个采样 token，在 rollout 日志里记录的 logprob 与训练侧重算出来的 logprob 对不上，差值落在千分之几到百分之一量级。单看这个差值不大，但它恰好落在 PPO 裁剪阈值的敏感区间里——重要性比率被数值噪声推过裁剪边界，本该参与梯度的 token 被裁掉，本该被裁掉的 token 反而保留。更麻烦的是 GRPO 的组内归一化：同一 prompt 的 G 条采样本应共享同一个基线，但每条样本的概率漂移方向不同，组内 advantage 的符号出现翻转，训练曲线在若干步内抖动后掉点。</p>\n<p>排查指向的不是权重同步、不是量化误差，而是批组成。rollout 引擎为了追吞吐，批调度器动态拼批：同一 prompt 在第 3 步落在 batch=48 的批里，在第 7 步落在 batch=17 的批里。attention 的 split-K 因子随批大小与序列长度自适应选择，GEMM 的 tile 归约顺序随 SM 占用情况变化，softmax 的 max 与 sum 归约树按 warp 划分切分。这些选择在单次前向里完全正确，但它们在两次前向之间不一致，于是同一组 logits 经过不同的浮点累加顺序，产出不同的 logprob。这不是精度不够，是**不可复现**。</p>\n<p>事故的代价可以直接折算成工程指标：为了压住抖动，调度器被迫按 prompt 分组、固定批形状、禁用 split-K 自适应，吞吐掉了一截；训练侧不得不把裁剪阈值放宽，等于用算法容错去吸收数值噪声，on-policy 的严格性被稀释。这就是批不变 Rollout 要解决的问题边界——它不提升单次前向的速度，它买的是「同一 prompt 在任何批位置下概率逐位一致」这个性质。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-2\">二 · 问题的精确表述：归约顺序是批的函数</h3>\n<p>把问题写成可检验的形式。设策略对动作 $y$ 在状态 $x$ 下的对数概率为 $\\log p(y|x)$，rollout 侧记为 $p_{\\text{rollout}}$，训练侧重算记为 $p_{\\text{train}}$。批不变性要求存在一个与批组成无关的确定性误差界：</p>\n<div class=\"formula\">$$\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right| \\le \\epsilon_{\\text{det}},\\quad \\text{ratio}=e^{\\Delta}\\in[1-\\epsilon,1+\\epsilon]$$</div>\n<p>其中 $\\Delta$ 就是两侧 logprob 之差。关键在于 $\\epsilon_{\\text{det}}$ 必须由内核的确定性保证，而不是由统计平均保证。非确定性内核下，$\\Delta$ 是批大小 $B$、序列长度 $L$、SM 占用率的函数，$\\epsilon_{\\text{det}}$ 无法给出上界，只能事后测量分布——这在工程上不可接受，因为裁剪阈值是一个硬门限，不是软约束。</p>\n<p>问题的根源在归约。attention score 的 softmax 需要跨序列维求 max 与 sum，GEMM 的 K 维累加需要跨 tile 求和，这两类归约在 stock 内核里都允许 split-K 与动态分块：split-K 因子随 $B$ 与 $L$ 选，块内 warp 划分随占用率选，跨块累加顺序随调度选。浮点加法不满足结合律，顺序一变，末位就变。单次误差在 FP32 下是 $O(\\sqrt{K})\\cdot\\text{ulp}$ 量级，但它在 RL 里被两层放大：一层是重要性比率的指数放大（$e^{\\Delta}$），一层是 GRPO 组内归一化把微小偏差转成 advantage 的符号噪声。</p>\n<p>这里必须划清边界。批不变 Rollout 处理的是**归约顺序导致的数值不可复现**，属于确定性内核层面。它不处理 NVFP4 量化带来的分布偏移——那是量化误差，需要量化稳定化路径单独处理；它也不处理异步权重同步的 staleness——那是版本错配，需要版本对齐与 staleness 校正。三者会在同一条流水线上叠加，但修法完全不同，混为一谈会导致内核定制做完之后抖动依旧。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-3\">三 · 机制：把归约顺序从批里摘出来</h3>\n<p>核心思路一句话：让 attention 与 GEMM 的归约按固定分块切分，跨块累加顺序与 batch 无关。rollout 引擎启动时加载批不变内核配置，锁定 attention 的 split-K 因子与 GEMM 的 tile 归约顺序；每个 decode step 按固定分块对 attention score 做 max 与 sum 归约，块内顺序固定，块间顺序固定，批大小只影响并行度而不影响求和树形状。softmax 与 layernorm 改用确定性归约树，禁用批相关的 split-K 变体。logprob 的计算路径写成：</p>\n<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>\n<p>其中 $z$ 为 logits，固定分块 max 与确定性 reduce 树保证归约顺序与 batch 无关。lm_head 与 softmax 走同一条确定性路径，禁止跨 batch 的动态并行归约。采样与 logprob 记录都使用这个确定性结果，于是同一 prompt 在不同 batch 下产出相同概率；训练侧用同一套确定性 kernel 重算，重要性比率与 GRPO 组内归一化都建立在这个逐位一致的 logprob 上。</p>\n<p>工程上还要加一道保险：对不一致样本按阈值标记，回退到高精度路径重算。这不是主路径，是兜底——当框架升级导致训练侧与 rollout 侧 kernel 版本错位时，标记机制能拦住污染样本而不是让噪声静默流入梯度。批调度器则获得了解放：组批时不再需要为数值一致性做特殊排序，可以自由追求吞吐，批形状不再被数值约束绑架。</p>\n<p>代价必须说清楚。固定 split-K 因子与确定性 reduce 树放弃了自适应 split-K 的并行度，长序列 attention 下速度低于 stock 内核，这个损失是可测的。确定性路径还要求 rollout 侧与训练侧 kernel 版本严格对齐，框架升级时需同步验证，否则「逐位一致」的前提直接失效。此外，内核需与 Blackwell 的 TMA 与 warp-specialized 流水线适配，定制成本高；适配不完整时，归约顺序仍可能随 batch 变化，等于白做。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-4\">四 · 适用边界：什么时候值得付这个代价</h3>\n<p>适用面由「是否需要跨批比较概率」决定。需要 off-policy 比率校正的场景——PPO 的裁剪、GRPO 的组内归一化、异步 rollout 的 staleness 校正——都在比较不同批位置下同一动作的概率，批不变性是刚需。尤其是异步 rollout：采样批与训练批天然错位，staleness 校正依赖比率 $e^{\\Delta}$ 的准确性，若 $\\Delta$ 里混着归约噪声，校正方向就是错的。这类场景下，固定归约换来的可复现性直接决定算法是否成立，吞吐损失是必要成本。</p>\n<p>反过来说，不适用或不必付代价的场景同样明确。纯推理服务没有训练侧重算，没有重要性比率，logprob 的可复现性不是 SLO 的一部分，此时固定 split-K 只是白白损失长序列吞吐。监督微调或不需要组内比较的 RL 变体，若裁剪阈值足够宽松、噪声不触发门限，也不值得上定制内核。还有一类是量化路径：与 NVFP4 的兼容需额外验证，若量化内核未保持确定性归约，logprob 逐位一致的前提被破坏，GRPO 组内比较仍会混入数值噪声——此时应先解决量化内核的确定性，而不是叠加批不变配置。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>是否需要批不变</th><th>主要代价</th></tr></thead><tbody><tr><td>同步 PPO/GRPO，批形状动态</td><td>需要，裁剪与组内归一化直接受影响</td><td>长序列 attention 吞吐低于 stock</td></tr><tr><td>异步 rollout + staleness 校正</td><td>需要，比率准确性是校正前提</td><td>kernel 版本需两侧严格对齐</td></tr><tr><td>纯推理服务</td><td>不需要，无可复现性 SLO</td><td>无收益，只有吞吐损失</td></tr><tr><td>NVFP4 量化 rollout</td><td>需先验证量化内核确定性</td><td>量化与确定性归约的兼容验证成本</td></tr></tbody></table>\n<p>规模上限也在这里。批不变内核的定制成本高，适配 TMA 与 warp-specialized 流水线不是配置项而是内核改造；吞吐预算紧张时，长序列下的速度损失会抵消可复现性收益。判断标准不是「要不要确定性」，而是「数值噪声是否已经触发算法门限」——若裁剪阈值被频繁误触发、组内 advantage 符号抖动，这笔账就该付；若门限宽松、噪声被算法容错吸收，则优先保吞吐。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-5\">五 · 一个具体例子：从事故到配置</h3>\n<p>回到开头的 GRPO 事故。修复路径不是调阈值，而是三步落地。第一步，rollout 引擎启动时加载批不变内核配置，锁定 attention 的 split-K 因子与 GEMM 的 tile 归约顺序，softmax 的 max 归约按固定分块切分，块内 warp 划分固定。第二步，采样与 logprob 记录走确定性 reduce 树，同一 prompt 在 batch=48 与 batch=17 下产出逐位一致的 logprob，rollout 日志里的 $\\Delta$ 归零。第三步，训练侧用同一版本 kernel 重算 logprob，重要性比率回到 1 附近，裁剪阈值不再被数值噪声触发，GRPO 组内 advantage 的符号抖动消失。</p>\n<p>修复后的系统指标变化是结构性的：调度器解除了批形状约束，可以按吞吐自由组批；训练侧不必放宽裁剪阈值，on-policy 的严格性恢复；代价是长序列 attention 的单步延迟上升，吞吐略低于 stock 内核。这个 trade-off 在事故背景下是划算的——抖动导致的掉点与重跑成本远高于内核吞吐损失。但如果这个任务是短序列、大批量、裁剪阈值宽松，同样的配置就是净损失，此时应保留 stock 内核并把确定性需求下推到只对 logprob 计算路径做固定归约，而不动 attention 主路径。</p>\n<p>这个例子给出的工程判断是：批不变 Rollout 的适用性由「算法是否在跨批比较概率」与「噪声是否已触发门限」两个条件共同决定，缺一不可。它买的是可复现性，卖的是并行度；在 Blackwell 上，这笔交易还必须叠加 TMA 与 warp-specialized 流水线的适配成本，以及 NVFP4 量化路径的兼容验证。配置之前先量 $\\Delta$ 的分布，再决定是否锁定 split-K——这是本算法唯一诚实的入场券。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-6\">六 · 批不变采样解决的是“概率不可复现”，不是“策略不稳”</h3>\n<p>先看一个线上事故的形态：RL 训练侧把同一 prompt 的 8 条 rollout 组成一个 GRPO 组，组内按 reward 归一化算优势。其中两条样本恰好落在 decode 批的不同位置——一条与长序列拼批、一条独占小批。由于 attention 的 split-K 因子与 GEMM tile 归约顺序随批组成变化，同一 token 的 logits 出现末位差异，softmax 后 logprob 偏差被放大到裁剪阈值附近。训练侧重算概率时重要性比率偏离 1，PPO 的 clip 被数值噪声触发，这两条样本的梯度被截断；更糟的是 GRPO 组内均值被污染，整组优势方向偏移。这不是策略更新本身的问题，而是采样侧与训练侧对同一动作给出了不同概率。批不变 Rollout 采样针对的正是这一类故障：它把“同一 prompt 在不同批位置下 logprob 逐位一致”作为可交付的工程契约，用固定分块归约把数值路径与 batch 组成解耦，使 $$\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right| \\le \\epsilon_{\\text{det}}$$ 中的 $\\epsilon_{\\text{det}}$ 收缩到浮点表示极限，ratio 落在 $[1-\\epsilon,1+\\epsilon]$ 的窄带内。</p>\n<p>它的机制边界很清晰：只处理归约顺序导致的不可复现，不处理量化误差导致的分布偏移（那是 NVFP4 量化稳定性的话题），也不处理异步权重同步带来的 staleness（那是另一条校正路径）。实现上，rollout 引擎启动即加载批不变内核配置，固定 attention 的 split-K 因子与 GEMM 的 tile 归约顺序；每个 decode step 对 attention score 按固定分块做 max 与 sum 归约，块内顺序与 batch 无关；lm_head 与 softmax 走确定性 reduce 树，禁止跨 batch 的动态并行归约，即 $$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$。采样与 logprob 记录共用这份确定性结果，训练侧用同一 kernel 重算，不一致样本按阈值标记并回退到高精度路径。批调度器因此不再需要为数值一致性做特殊排序，可以自由组批追求吞吐——这是它换来的调度自由度。</p>\n<p>代价必须提前算清。固定 split-K 与确定性 reduce 树放弃了 stock 内核的部分并行度，长序列 attention 下速度低于常规实现，若吞吐预算紧张，可复现性收益会被抵消。定制内核需与 Blackwell 的 TMA 和 warp-specialized 流水线适配，适配不完整时归约顺序仍可能随 batch 漂移；与 NVFP4 量化路径的兼容要额外验证，量化内核若未保持确定性归约，逐位一致的前提即被破坏。适用边界因此收窄：它适合需要 off-policy 比率校正与 GRPO 组内比较的 RL rollout，尤其是异步 rollout 的 staleness 校正场景；对不依赖组内比较、只做纯采样吞吐的离线数据生产，则不值得付出这份内核定制成本。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>批不变采样</th><th>相邻方案</th></tr></thead><tbody><tr><td>失效来源</td><td>批组成与归约顺序</td><td>量化误差 / 权重 staleness</td></tr><tr><td>解决层次</td><td>确定性内核</td><td>数值精度 / 同步策略</td></tr><tr><td>主要代价</td><td>长序列吞吐损失、定制成本</td><td>精度损失、收敛节奏</td></tr></tbody></table>\n<h3 id=\"alg-batch-invariant-rollout-sec-7\">七 · 内核配置装载：把“批无关”钉进启动参数</h3>\n<p>批不变 Rollout 的第一步不在请求到达时发生，而在引擎启动时完成：rollout 引擎加载一份批不变内核配置，把 attention 的 split-K 因子与 GEMM 的 tile 归约顺序写成编译期或启动期常量。输入是硬件档位（SM100/SM103）、并行拓扑、KV 布局与量化路径；输出是一组固定了归约形状的 kernel 变体及其调度表。代价落在启动延迟与显存占用上：每个确定性变体都要独立占用指令缓存与常量区，且不能与 stock 内核共享同一份 split-K 自动调优缓存，因此引擎常驻显存中的 kernel 代码段比纯吞吐配置更大。具体例子：在 GB200 NVL72 的一个推理实例上，attention 的 split-K 因子被固定为某一常量，decode 阶段无论 batch 是 1 还是 256，跨块的 max 与 sum 都按同一棵归约树累加，调度器不再有机会为“更小的 batch 选更细的 split”而改变数值路径。</p>\n<p>这一步的关键判断是：固定 split-K 因子等于主动放弃 split-K 的自适应收益。split-K 的本质是把一个 K 维归约切成多段并行、再跨段合并，段数随 batch 与序列形状浮动，合并顺序随之浮动，这正是 logits 随 batch 组成漂移的源头之一。把段数与合并顺序钉死，换来的是数值路径的单一性；代价是长序列 attention 下并行度被压低，kernel 性能相对 stock 实现有可测损失。配置装载还必须与 TMA 和 warp-specialized 流水线对齐：TMA 的搬运分块若随 batch 变化，warp-specialized 的 producer/consumer 阶段划分就会间接改变归约的到达顺序，因此分块尺寸与流水级数也要一并固定。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-8\">八 · 组批与 token 入队：调度器卸下数值包袱</h3>\n<p>请求进入调度器后，组批逻辑的输入是待处理请求队列、每请求的已生成 token 数与 KV 页状态；输出是一个 batch 的 token 集合与对应的 KV 页映射。这一步的代价是调度自由度与显存带宽的权衡：批越大，decode 的 GEMM 越接近饱和，HBM 带宽利用率越高；但批越大，KV 页的跨请求拼接越复杂，页表遍历的元数据开销上升。批不变机制在这里的直接收益是调度器不再需要为数值一致性做特殊排序——它不必把同一 prompt 固定在同一 batch 位置，也不必为避免跨 batch 归约而限制批形状，可以纯粹按吞吐与 SLO 组批。</p>\n<p>用伪代码表达组批约束的松弛：</p>\n<div class=\"formula\">$$\\text{batch} = \\mathrm{Scheduler}(Q, \\text{SLO}_{\\text{tput}}),\\quad \\text{约束集} = \\{\\text{KV 页容量},\\ \\text{SLO 延迟}\\}\\setminus\\{\\text{数值一致性}\\}$$</div>\n<p>具体例子：连续批处理场景下，一个长 prompt 的 decode 请求可以与若干短请求拼进同一批，调度器按 KV 页剩余容量与 decode 步预算决定拼法，而不必担心“长短混批导致归约树形状不同”。代价体现在 KV 页管理上：批组成自由后，跨请求的 KV 页拼接更频繁，页表查询与页拷贝的带宽开销上升，这部分开销由调度器承担，而非由数值路径承担。若 KV 页碎片化严重，组批自由度反而被页容量约束吃掉，此时批不变内核的收益主要体现在概率可复现性上，而非吞吐。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-9\">九 · Decode step 的 attention 归约：固定分块的 max 与 sum</h3>\n<p>每个 decode step 的核心是 attention score 的归约。输入是当前 token 的 query、KV 页中历史 key/value、以及固定分块参数；输出是 attention 输出向量与该 token 的 logits 前置状态。机制上，attention score 按固定分块切分，块内做 max 与 sum 归约，跨块累加顺序与 batch 无关；块内顺序同样被钉死，不随 batch size 变化。这一步的代价最直接：固定分块牺牲了 split-K 的并行度，长序列下 attention 的 K 维并行被限制在固定段数内，SM 占用率下降，单 step 延迟上升。</p>\n<p>公式化地写出这一归约的批无关性：</p>\n<div class=\"formula\">$$\\mathrm{attn}(q,K,V)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\{\\mathrm{softmax}_{\\mathrm{chunk}}(qK^{\\top}_c)\\cdot V_c\\}\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>\n<p>具体例子：一个 decode 步内，batch 中混有已生成 8k token 的长请求与刚起步的短请求。长请求的 attention 需要跨更多 KV 块，若 split-K 因子随序列长度浮动，跨块合并顺序就会与短请求不同，同一 prompt 在不同批位置下的 logprob 便出现漂移。固定分块后，长请求的跨块累加仍走同一棵归约树，只是块数更多，树的形状不变。代价是长序列 attention 的吞吐低于 stock 内核，若吞吐预算紧张，可复现性收益会被延迟损失抵消。NVFP4 量化路径在此需额外验证：量化内核若未保持确定性归约，逐位一致的前提即被破坏。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-10\">十 · lm_head 与 softmax 的 logprob 路径：确定性 reduce 树</h3>\n<p>attention 输出进入 lm_head 与 softmax，得到采样所需的概率分布与 logprob。输入是隐状态与固定分块参数；输出是该 token 的 logprob 记录，写入 rollout 轨迹供训练侧重算。机制要求 lm_head 与 softmax 使用确定性 reduce 树，禁止跨 batch 的动态并行归约——即 softmax 的 max 与 sum 不得因 batch 内其他请求的存在而改变分块方式。这一步的代价是 softmax 的向量化宽度被固定，无法按 batch 内实际 token 数动态调整并行度，词表很大时单 token 的 softmax 延迟略高于自适应实现。</p>\n<p>核心公式即本算法的数值契约：</p>\n<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\left|\\log p_{\\text{rollout}}(y|x)-\\log p_{\\text{train}}(y|x)\\right|\\le\\epsilon_{\\text{det}}$$</div>\n<p>具体例子：同一 prompt 在 batch size 为 4 与 batch size 为 64 时各采样一次，两次的 logprob 逐位一致，重要性比率 $\\text{ratio}=e^{\\Delta}$ 落在 $[1-\\epsilon,1+\\epsilon]$ 内，PPO/GRPO 的裁剪阈值不再被数值噪声触发。代价是 logprob 记录本身的存储开销：每个 token 都要落一份 logprob 与对应的确定性 kernel 版本标识，轨迹存储的带宽与显存占用上升；若轨迹长度大，这部分开销不可忽略。采样与 logprob 记录必须使用同一确定性结果，不能一边用自适应 softmax 采样、一边用确定性 softmax 记 logprob，否则比率校正的基准就错位了。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-11\">十一 · 训练侧重算与不一致回退：阈值判定与高精度路径</h3>\n<p>训练侧拿到 rollout 轨迹后，用同一确定性 kernel 重算 logprob，输入是轨迹中的 token 与上下文，输出是重算 logprob 与差值 $\\Delta$。机制上，对不一致样本按阈值标记并回退到高精度路径重算：差值超过 $\\epsilon_{\\text{det}}$ 的样本不走常规重算，而是切到高精度（如 FP32 归约）路径再算一遍，确认是数值路径问题还是策略本身已偏移。这一步的代价是重算的算力开销与回退路径的延迟尖峰：高精度路径的吞吐远低于常规路径，若不一致样本比例上升，训练侧的吞吐会被拖累。</p>\n<p>判定逻辑可写成：</p>\n<div class=\"formula\">$$\\text{flag}=\\mathbb{1}\\big[\\left|\\log p_{\\text{rollout}}-\\log p_{\\text{train}}\\right|&gt;\\epsilon_{\\text{det}}\\big],\\quad \\text{flag}=1\\Rightarrow \\text{recompute}_{\\text{high-precision}}$$</div>\n<p>具体例子：GRPO 组内比较要求同一 prompt 的多个采样在同一基准下归一化，若某样本因 kernel 版本错配导致 logprob 偏差，组内优势估计就被污染。回退路径把这类样本单独拎出来重算，避免污染扩散到整组。代价是确定性路径需与训练侧 kernel 版本严格对齐，框架升级时需同步验证——rollout 引擎与训练框架的 kernel 版本一旦错位，重算的就不是同一棵归约树，阈值判定会误报。这是本算法最脆弱的工程接口：版本对齐的成本落在发布流程上，而非单次推理的延迟上。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-12\">十二 · 流水线适配与吞吐账：TMA、warp-specialized 与量化路径</h3>\n<p>最后一步是把上述确定性路径嵌入 Blackwell 的 TMA 与 warp-specialized 流水线。输入是分块参数、流水级数与量化配置；输出是实际执行的 kernel 流水。机制上，TMA 的搬运分块必须与归约分块对齐，warp-specialized 的 producer/consumer 阶段划分必须固定，否则流水线的到达顺序会间接改变归约顺序，出现“配置写了固定、运行时仍随 batch 变化”的失败模式。这一步的代价是流水线深度被限制：固定分块后，TMA 搬运的粒度不能按 batch 动态调整，流水级数偏保守，HBM 带宽利用率低于全自适应流水线。</p>\n<p>吞吐账可以定性表述：固定 split-K 与确定性 reduce 牺牲部分并行度，长序列 attention 下速度低于 stock 内核；批不变内核定制成本高，适配不完整时归约顺序仍可能随 batch 变化。具体例子：在 NVFP4 量化路径上，若量化 kernel 的归约未保持确定性，logprob 逐位一致的前提被破坏，GRPO 组内比较仍混入数值噪声——此时即使 attention 与 softmax 路径已固定，量化层的非确定性归约会重新引入漂移。工程判断是：批不变 Rollout 的收益不在单步延迟，而在调度器卸下数值一致性约束后换来的组批自由度与比率校正的干净基准；代价则集中在长序列吞吐与 kernel 版本对齐的维护成本上。若吞吐预算紧张且序列普遍偏长，这笔交换未必划算；若 rollout 以异步、大批、组内比较为主，固定归约换来的是可复现的概率基准，这是 off-policy 校正能成立的前提。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-13\">十三 · 批不变内核的失效边界与系统代价</h3>\n<p>批不变内核把“同一 token 的 logprob 逐位一致”当作硬约束，代价立刻落在并行度上。stock 内核在长序列 attention 里用 split-K 把 K 维切成多段并行归约，段数随 batch 与序列长度动态选择，以填满 SM；批不变路径把 split-K 因子钉死，跨段累加顺序写成与 batch 无关的固定树，于是同一份 KV 只能按固定分块推进，空闲 SM 无法用额外切分吸收。GEMM 侧同理，tile 归约顺序固定后，原本可按批形状重排的累加链被锁死。结果是长序列 decode 下该路径速度低于 stock 内核，吞吐预算紧张时，可复现性收益会被这部分损失抵消——这是方案的第一条硬边界，不是调参能绕过的。</p>\n<p>第二条边界在量化路径。NVFP4 的块缩放与反量化本身带归约，若量化内核在反量化时按 batch 动态选择并行归约，logprob 的逐位一致前提就被破坏，GRPO 组内比较重新混入数值噪声。因此批不变配置必须与量化内核的归约策略一起验证：<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>该式只在 softmax 分块 max 与 reduce 树都固定时成立，量化反量化若插入批相关归约，等号右侧就不再是 batch 无关量。适配 Blackwell 的 TMA 与 warp-specialized 流水线时，定制成本高；适配不完整时会出现归约顺序仍随 batch 变化的隐性失效，表现为同一 prompt 在不同批下 logprob 尾部几位抖动，阈值标记与高精度回退被频繁触发，反而拉高延迟。</p>\n<p>第三条边界是版本对齐。确定性路径要求 rollout 侧与训练侧 kernel 版本严格一致，框架升级时需同步验证两侧归约树与分块参数；一侧升级而另一侧未跟，重要性比率 <span>ratio</span> 就会偏离 1，PPO/GRPO 的裁剪阈值被数值噪声触发。工程上应把内核配置哈希写入每条 rollout 样本的元数据，训练侧重算前比对哈希，不一致即走回退路径。下表按请求流动顺序列出各步的输入、输出与代价：</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>系统代价</th></tr></thead><tbody><tr><td>加载批不变内核配置</td><td>固定 split-K 因子、GEMM tile 归约顺序</td><td>确定性 kernel 句柄</td><td>启动期一次性开销，配置与 TMA 流水线绑定</td></tr><tr><td>decode step attention 归约</td><td>固定分块 score</td><td>与 batch 无关的 max/sum</td><td>放弃动态 split-K，长序列下 SM 占用下降</td></tr><tr><td>lm_head + softmax 记 logprob</td><td>logits <span>z</span></td><td>逐位一致 logprob</td><td>禁用跨 batch 动态并行归约，尾延迟变长</td></tr><tr><td>训练侧重算与比率</td><td>样本元数据、内核哈希</td><td>重要性比率、组内归一化</td><td>哈希不一致触发高精度回退，增加重算量</td></tr></tbody></table>\n<p>调度器侧因此获得一项自由：组批不再需要为数值一致性做特殊排序，可自由追求吞吐，批形状随负载动态变化而不影响 logprob。但这项自由只在上述三条边界内成立——长序列 attention 的吞吐损失、NVFP4 量化内核的确定性验证、双侧 kernel 版本同步，任何一条失守，批不变假设即退回为“批相关但抖动较小”的弱保证。工程判断是：把批不变内核当作可复现性的基础设施而非免费加速，在吞吐预算允许的序列长度区间内启用，超出区间则显式切回 stock 内核并在样本元数据中标注，让训练侧的比率校正知道这批数据的概率不是逐位可复现的。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-14\">十四 · 把“批不变”写成一条可证明的误差界</h3>\n<p>批不变 Rollout 的核心命题不是“结果看起来一样”，而是一条可检验的误差界：同一 prompt 的同一 token，在 rollout 侧与训练侧重算侧的对数概率差必须被确定性归约压到阈值以内，从而让重要性比率落在裁剪区间内。给定事实给出的判据是</p>\n<div class=\"formula\">$$\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right| \\le \\epsilon_{\\text{det}},\\quad \\text{ratio}=e^{\\Delta}\\in[1-\\epsilon,1+\\epsilon]$$</div>\n<p>逐项解释：$\\log p_{\\text{rollout}}$ 是采样时记录的 token 对数概率，$\\log p_{\\text{train}}$ 是训练侧用同一确定性 kernel 重算的值；$\\Delta$ 是两者之差，$\\epsilon_{\\text{det}}$ 是确定性归约允许的残差上界，$\\epsilon$ 则是比率层面的等效容差。关键一步在于把 $\\Delta$ 拆成两部分：一部分来自归约顺序（batch 组成、split-K 因子、分块边界），另一部分来自 kernel 版本与量化路径的差异。前者正是本算法要消掉的对象——固定分块与固定归约树使顺序项恒等于零，$\\Delta$ 只剩版本对齐项，于是 $\\epsilon_{\\text{det}}$ 可以取到极小。反过来，若顺序项未被消除，$\\Delta$ 随 batch size 抖动，$\\text{ratio}$ 就会在 1 附近随机游走，PPO 的裁剪阈值被数值噪声触发，GRPO 的组内归一化把不同 batch 下的同一动作排出不同名次。</p>\n<p>工程代价直接体现在这里：$\\epsilon_{\\text{det}}$ 越紧，对 kernel 确定性的要求越硬，可用的并行变体越少。固定 split-K 因子意味着长序列 attention 放弃按序列长度动态扩张的并行度，prefill 段与长上下文 decode 的吞吐相对 stock 内核有可测损失。这是一个明确的取舍：用一部分 kernel 峰值性能换 $\\Delta$ 的可证界。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-15\">十五 · 核心公式的第二形式：归约树与 batch 的正交性</h3>\n<p>可用事实给出的另一条等价写法把 logprob 直接写成归约树的输出：</p>\n<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>\n<p>$z$ 是 lm_head 输出的 logits，$\\mathrm{softmax}_{\\mathrm{chunk}}$ 表示按固定分块先做块内 max 再归约，$\\mathrm{ReduceTree}_{\\mathrm{fixed}}$ 是确定性归约树。正交性符号 $\\mathrm{order}(\\cdot)\\perp\\mathrm{batch\\ size}$ 是本算法的全部内容：归约的求和/求最大顺序只由分块参数决定，不由当前 batch 里有几条请求、每条多长决定。</p>\n<p>推导的关键一步是 softmax 的数值稳定化。标准写法先减全局 max 再指数求和，而全局 max 的求法若采用跨 batch 的动态并行归约（例如按当前 batch 的 token 总数切分 reduce 段），max 的归约顺序就随 batch 组成变化；即便数学上 max 与顺序无关，浮点加法与比较的结合次序仍会带来末位差异，经指数放大后进入 logprob。固定分块的做法是：块大小写死，块内 max 顺序写死，跨块 max 与 sum 用固定树形归约，块数由序列长度决定而与 batch 无关。于是同一 token 的 logits 无论落在 batch 的哪个位置，走的都是同一条归约路径，逐位一致。</p>\n<p>系统代价落在寄存器与共享内存的占用上：固定分块意味着分块大小不能随 SM 占用率动态调整，warp-specialized 流水线里负责归约的 warp 组必须按最坏分块预留缓冲，occupancy 因此被压低一档。在 Blackwell 的 TMA 搬运与 tcgen05 MMA 流水线中，这一档占用率损失表现为 decode 阶段每步的发射间隔略微拉长，属于可测但可控的量级。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-16\">十六 · 伪代码：从 kernel 配置到 logprob 落盘</h3>\n<p>把机制落到可实现层面，需要三段伪代码思路。第一段是引擎启动时的内核配置加载：</p>\n<ul>\n<li>读取批不变内核配置，写入 attention 的 split-K 因子 $K_f$ 与 GEMM 的 tile 归约顺序表；这两个量在整个进程生命周期内不变，不随请求到达率或 batch size 调整。</li>\n<li>为 lm_head 与 softmax 绑定确定性 reduce 树：块大小 $C$、块内归约方向、跨块树深度全部固定；禁用跨 batch 的动态并行归约开关。</li>\n<li>记录 kernel 版本指纹，与训练侧配置比对；不一致则拒绝启动或降级到高精度重算路径。</li>\n</ul>\n<p>第二段是每个 decode step 的归约路径，伪代码思路如下：对 attention score 按固定块 $C$ 切分，块内先做 max 再减、指数、求和，跨块用固定树合并；对 lm_head 输出 $z$ 走同一条确定性树得到 $\\log p$；采样依据该 $\\log p$ 进行，并把 token id 与该 $\\log p$ 一并写入 rollout 记录。这里的关键约束是采样与记录必须使用同一个确定性结果——若采样用一条快速路径、记录用另一条，比率校正立刻失效。</p>\n<p>第三段是训练侧重算与不一致回退：训练侧加载同一份确定性 kernel 重算 $\\log p_{\\text{train}}$，逐 token 比对 $\\Delta$；超过 $\\epsilon_{\\text{det}}$ 的样本被标记，回退到高精度路径（更高精度累加或禁用分块优化的参考实现）重算后再进入比率计算。回退比例本身是一个运维指标：它上升说明两侧 kernel 版本或量化路径已经漂移。</p>\n<p>代价方面，记录 $\\log p$ 使 rollout 输出张量多一份与 token 等长的浮点负载，按每 token 一个标量计，对显存带宽的增量相对 KV cache 读取是小项，但对输出落盘与跨进程传输（分离式部署下经 NIXL 搬运）是实打实的字节数增加；回退路径则是延迟尖峰来源，单样本重算会把该 step 的尾延迟抬高。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-17\">十七 · 与 NVFP4、TMA 的适配：确定性必须穿透量化路径</h3>\n<p>本算法处理的是归约顺序导致的不可复现，而 NVFP4 量化稳定化处理的是量化误差导致的分布偏移——两者是不同层面的问题，但会在同一条 kernel 上叠加。若量化内核在反量化与累加阶段采用了随 batch 变化的归约策略，那么即便 attention 与 GEMM 主路径已经批不变，logprob 的逐位一致前提仍被破坏，GRPO 组内比较继续混入数值噪声。因此适配检查必须穿透到量化路径：确认 NVFP4 的块缩放因子计算与累加顺序同样走固定树，确认反量化后的累加不引入 split-K 变体。</p>\n<p>与 Blackwell 的 TMA 和 warp-specialized 流水线适配是定制成本的主要来源。TMA 的搬运粒度与流水线阶段数通常按吞吐调优，而固定分块要求这些参数与归约块大小对齐；对齐不完整时，可能出现搬运按动态粒度切分、归约却按固定块合并的错位，表现为归约顺序仍随 batch 变化——这正是失败模式之一。工程判断是：把分块参数与 TMA 描述符一起纳入版本指纹，任何一侧改动都触发全链路一致性验证，而不是只验证 attention 单算子。</p>\n<p>吞吐代价在此处最直观：固定 split-K 因子放弃了按序列长度扩张并行度的能力，长序列 attention 下速度低于 stock 内核；若推理集群的吞吐预算本就紧张，可复现性收益会被抵消。可行的折中是分层策略——对参与比率校正的 rollout 请求走确定性路径，对不参与校正的辅助请求（如评测采样）走 stock 内核，用调度标签区分，而不是全局降速。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-18\">十八 · 批调度器的解放与它的边界</h3>\n<p>公式的直接推论是调度器约束的解除。既然 $\\mathrm{order}(\\cdot)\\perp\\mathrm{batch\\ size}$，组批时就不需要为数值一致性做特殊排序——不必把同 prompt 的请求凑进同一批，不必限制批形状，可以自由追求吞吐：连续批处理按到达顺序拼批，chunked prefill 与 decode 混批，批大小随负载动态伸缩。这是本算法相对“为一致性牺牲批形状”的旧做法的实质收益。</p>\n<p>但解放有边界。第一，确定性路径与训练侧 kernel 版本必须严格对齐，框架升级（TensorRT-LLM、vLLM、SGLang 任一侧的内核更新）都要同步验证，否则 $\\Delta$ 的版本项重新抬头。第二，固定归约牺牲并行度带来的吞吐损失在长序列场景最重，容量规划时要把这部分损失计入 token/s 预算，而不是按 stock 内核的峰值估算。第三，回退到高精度路径的样本会制造尾延迟尖峰，SLO 以 logprob 可复现性为主时这可以接受，以 P99 延迟为主时需要在调度层为回退样本预留配额。</p>\n<p>一个具体例子可以说明边界在哪里：异步 Rollout 流水线中，rollout 侧与训练侧存在权重 staleness，比率校正本就承担着校正分布偏移的职责；此时若再叠加 batch 组成引起的 $\\Delta$ 抖动，校正信号会被双重污染，裁剪阈值频繁触发。批不变内核把其中一项噪声压到零，使 staleness 校正成为比率偏差的唯一显著来源——这正是本算法与异步权重同步相邻而不重叠的分工。反过来，若部署中 NVFP4 量化路径未验证确定性，回退比例上升会成为第一个报警信号，此时应优先检查量化内核的归约树而非调度策略。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-19\">十九 · 批不变内核的失效边界与吞吐账</h3>\n<p>批不变内核并非在所有路径上都能兑现“逐位一致”。核心公式的成立依赖一个隐含前提：从 logits 到 logprob 的整条链路都走同一套确定性归约。可写为 <span class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</span> 其中 $z$ 为 logits，固定分块的 max 与确定性 reduce 树保证归约顺序与 batch 无关。一旦链路中任一环节被替换成批相关实现——例如 lm_head 的 GEMM 启用了随 batch 动态选择的 split-K 因子，或 softmax 走了跨 batch 的动态并行归约——$\\Delta=\\log p_{\\text{rollout}}-\\log p_{\\text{train}}$ 就会重新随批组成漂移，比值 $\\mathrm{ratio}=e^{\\Delta}$ 逃出 $[1-\\epsilon,1+\\epsilon]$ 区间，PPO/GRPO 的裁剪阈值被数值噪声而非策略变化触发。因此失效条件不是“kernel 写得不够快”，而是“确定性契约被局部破坏”：固定 split-K 因子、确定性 reduce 树、固定分块 softmax max 三者必须同时生效，缺一即退化为 stock 行为。</p>\n<p>最典型的破坏源是量化路径。NVFP4 量化稳定处理的是量化误差导致的分布偏移，异步权重同步处理的是 staleness，而本方案处理的是 batch 组成与归约顺序导致的数值不可复现，属于确定性内核层面——三者正交，不能互相替代。若 NVFP4 的量化 GEMM 内核未保持确定性归约（例如为吞吐在 tile 级引入随 batch 变化的累加顺序），则 logprob 逐位一致的前提被直接破坏，GRPO 组内比较仍混入数值噪声，而此时误差来源已从“归约顺序”变成“量化+归约”的耦合，阈值 $\\epsilon_{\\text{det}}$ 的标定也不再可信。工程判断是：量化路径与本方案必须联合验证，不能假设“量化内核天然确定”。</p>\n<p>系统代价集中在并行度上。固定 split-K 因子与确定性 reduce 树放弃了 stock 内核按 batch 形状动态选择 split-K、动态并行归约的自由，长序列 attention 下并行度受限最明显，速度低于 stock 内核；材料只说明“速度略低于 stock 内核”，未给出具体批大小与 SLO 数值，因此吞吐损失需按实际负载实测，不能套用固定比例。这笔账要和可复现性收益对抵：若吞吐预算紧张、组内比较对噪声不敏感，固定归约的收益会被抵消；反之在异步 rollout 的 staleness 校正场景，$\\mathrm{ratio}$ 接近 1 带来的裁剪稳定性通常值得这点损失。另一项代价是版本对齐——确定性路径需与训练侧 kernel 版本严格一致，框架升级时必须同步验证，否则 rollout 与训练重算落到不同归约树，比特级对齐失效。</p>\n<p>部署侧还有适配成本。批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线适配，定制成本高；适配不完整时可能出现归约顺序仍随 batch 变化——表面加载了“批不变配置”，实际 TMA 搬运与流水线切分仍按 batch 动态调整分块，导致同一 token 在不同 batch size 下 logprob 不一致。可落地的检查手段是在固定 prompt 上扫多个 batch size，逐位比对 logprob 记录；一旦发现差异，回退到高精度路径重算并按阈值 $\\epsilon_{\\text{det}}$ 标记样本，而不是放宽阈值掩盖。批调度器此时才真正获得自由：组批不再需要为数值一致性做特殊排序，可自由追求吞吐，这是本方案对调度侧最直接的回报。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-20\">二十 · 请求形态：批量 decode 是唯一甜点区</h3>\n<p>批不变内核的负载配方第一条，是请求形态必须落在「RL rollout 的批量 decode」上。原因不在算法偏好，而在归约结构：prefill 阶段的 attention 是长序列上的大归约，天然倾向 split-K 并行；decode 阶段每步只追加一个 token，attention score 的归约维度是 KV 长度，分块后可固定块数与块内顺序。批不变内核把 decode 的 max 与 sum 归约按固定分块切分，块内顺序与 batch 无关，这正是它能在动态批大小下保持逐位一致的前提。一旦请求形态滑向长 prefill 或混合 prefill/decode 背驮，固定 split-K 因子就成了硬约束：prefill 侧为了吞吐想开更大 split-K，而批不变路径不允许因子随 batch 组成浮动，两边拉扯的结果是 prefill 被迫退回低并行度配置，长序列 attention 下速度低于 stock 内核。工程判断很直接——把批不变内核限定在 decode 侧，prefill 走常规高并行内核，两侧在 KV 上衔接，而不是让一套确定性配置吃下所有形态。</p>\n<p>请求形态还决定 logprob 记录点的位置。批量 decode 每步产出 token 与对应 logprob，采样与记录共用同一条确定性 reduce 树，训练侧重算时用同一 kernel 版本即可对齐。若请求形态是流式逐 token 返回、客户端随时中断，记录点会被截断在半步，训练侧重算的序列边界与 rollout 侧不一致，逐位一致的前提被破坏。因此配方要求 rollout 侧以「完整 step」为记录粒度，中断请求要么补齐 step 边界要么整段丢弃。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-21\">二十一 · 长度分布：短中序列是主战场，长尾要隔离</h3>\n<p>长度分布对批不变内核的代价曲线影响是非线性的。decode 每步的 attention 归约量随 KV 长度增长，固定分块意味着块数随长度上升，跨块累加的串行段变长；短序列下这段开销被 GEMM 与 lm_head 掩盖，中序列下开始显形，长序列下成为主导。材料只定性说明「长序列 attention 下速度低于 stock 内核」，没有给拐点数值，工程上应把长度分布当作配方的一等输入：把 P50 落在中短区间的请求喂给批不变路径，把超过某分位的长尾请求路由到 stock 内核路径，并在训练侧对这批样本单独标记，避免它们污染 GRPO 组内比较。</p>\n<p>更隐蔽的问题是同一 prompt 组内的长度方差。GRPO 要求同组样本可比，若组内一条样本走批不变路径、另一条因长度超阈值走 stock 路径，两条的 logprob 归约顺序不同，组内归一化就混入了路径差异而非策略差异。配方因此要求路由以「组」为单位而非以「请求」为单位：同组样本要么全走确定性路径，要么全走 stock 路径并整组退出本轮比较。长度分桶在组批时按组内最大长度对齐，而不是按单请求长度各自分桶。</p>\n<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>\n<p>这条式子里的「order 与 batch size 无关」在长度维度上有对偶要求：块数可以随序列长度变，但块内归约顺序与跨块累加顺序不能随 batch 组成变。长度分桶若把不同长度的请求塞进同一 batch，padding 会改变有效块数，跨块累加的分段边界随之漂移，逐位一致就失守。所以配方要求同 batch 内长度对齐到固定分块粒度，padding token 的归约结果被掩码剔除但分段结构保持不变。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-22\">二十二 · 并发与批大小：动态批是卖点，也是压力源</h3>\n<p>批不变内核的核心卖点写在机制里：批调度器组批时不再需要为数值一致性做特殊排序，可自由追求吞吐。这意味着并发与批大小可以随负载动态起伏，同一 prompt 在 batch=8 与 batch=64 下产出相同概率。但「自由组批」不等于「无成本组批」。固定 split-K 因子与确定性 reduce 树牺牲了部分并行度，batch 越大，GEMM 侧 tile 归约的固定顺序越难吃满 SM；batch 越小，decode 每步的固定开销占比越高。配方给出的判断是：批大小应维持在能摊薄固定归约开销的区间，同时不因过大而让固定 tile 顺序成为 GEMM 的瓶颈。材料未给具体批大小数值，工程上以「固定开销占比」与「GEMM 利用率」两条曲线交叉点定档。</p>\n<p>并发维度的真正风险在异步 rollout。异步流水线里不同 step 的 batch 组成持续变化，批不变内核恰好是为这种场景设计的——它让 staleness 校正所依赖的重要性比率不被数值噪声污染。但异步也意味着同一 prompt 的多次采样可能落在不同并发档位，若某档位触发了内核配置切换（例如超过某阈值启用不同分块策略），逐位一致就在档位边界断裂。配方要求内核配置在引擎启动时一次性加载并锁定，运行期不因并发变化重选分块，档位切换只允许发生在组边界。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>配方取值倾向</th><th>越界后果</th></tr></thead><tbody><tr><td>请求形态</td><td>批量 decode，prefill 走 stock</td><td>长 prefill 拖低并行度，吞吐低于 stock</td></tr><tr><td>长度分布</td><td>中短为主，长尾按组隔离</td><td>组内路径分裂，GRPO 比较混入路径差异</td></tr><tr><td>批大小</td><td>动态但锁配置，组边界切换</td><td>档位边界处逐位一致断裂</td></tr><tr><td>并发</td><td>异步流水线，配置启动期锁定</td><td>运行期重选分块破坏可复现性</td></tr></tbody></table>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-23\">二十三 · 负载不对时：三种可观测的失效</h3>\n<p>第一种失效是吞吐预算被确定性开销吃掉。固定 split-K 与确定性 reduce 牺牲并行度，长序列 attention 下速度低于 stock 内核；若集群吞吐预算紧张，可复现性收益被速度损失抵消，SLO 从「logprob 可复现 + 吞吐」退化为只保吞吐。可观测信号是 decode step 的固定开销占比随长度上升而单调爬升，同时 GEMM 利用率不随 batch 增大而改善——两条曲线同时走坏即判定负载配方越界。</p>\n<p>第二种失效是适配不完整导致的假确定性。批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线适配，定制成本高；适配不完整时可能出现归约顺序仍随 batch 变化。这种失效最危险，因为表面指标（吞吐、显存）正常，只有把同一 prompt 在不同 batch 下重放并逐位比对 logprob 才能暴露。配方要求把「跨 batch 重放比对」做成上线前的固定验收项，而不是依赖训练侧重要性比率的统计异常来事后发现。</p>\n<p>第三种失效是量化路径破坏确定性归约。与 NVFP4 量化路径的兼容需额外验证，若量化内核未保持确定性归约，logprob 逐位一致的前提被破坏，GRPO 组内比较仍混入数值噪声。量化误差本身由 NVFP4 稳定化那条线处理，但量化内核若在 reduce 阶段引入批相关的 split 变体，两条防线的假设同时失效。配方要求量化路径与批不变路径的交叉点单独验证：同一 prompt 在量化开与关、batch 大与小时四象限比对，任一象限不一致即判定该量化内核不可用于 rollout 记录。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-24\">二十四 · 配方落地：把负载约束写进调度器</h3>\n<p>负载配方最终要落到调度器的组批逻辑里，而不是留给运维口头约定。具体做法是给每个请求打三个标签：形态（decode/prefill）、长度桶（按固定分块粒度对齐）、组 ID（GRPO 同组标识）。组批时先按组 ID 聚合，组内长度对齐后整组进同一 batch；prefill 请求单独走 stock 队列，不进入确定性路径；长度超阈值的组整组路由到 stock 并标记退出本轮比较。批大小在组边界处允许变化，内核配置在启动期锁定，运行期只读。</p>\n<p>这套调度的代价是可观测的：组聚合降低了组批自由度，短组等待长组对齐会引入排队延迟；prefill 与 decode 分队列意味着 KV 交接点需要显式同步，分离式预填/解码那条线的衔接机制在此复用一句话即可。收益是把数值一致性从「内核碰巧对上」变成「调度保证对上」，重要性比率接近 1、PPO/GRPO 裁剪阈值不被数值噪声触发的效果才可稳定复现。工程判断落在最后一句：批不变内核不是万能加速器，它是一份用并行度换可复现性的合约，负载配方就是这份合约的适用条款——条款之外的请求，宁可不走这条路。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-25\">二十五 · 负载配方与失效边界：批不变内核在什么请求形态下才划算</h3>\n<p>批不变内核的收益不是无条件成立的，它绑定在一类特定的负载形态上：RL rollout 的批量 decode，批大小随调度器动态伸缩，同一 prompt 会在不同 batch 位置被反复采样，SLO 的第一优先级是 logprob 可复现性，吞吐退居其次。这个配方里，请求长度分布决定了代价的量级——短序列 decode 时，attention 的归约开销占比低，固定 split-K 因子与确定性 reduce 树带来的并行度损失被 GEMM 与 lm_head 的固定 tile 归约摊薄，速度相对 stock 内核只有可测但不致命的下降；一旦序列拉长，attention score 的 max 与 sum 归约成为主耗时项，固定分块切分放弃了跨块动态并行的机会，长序列下的吞吐损失就会显性化。换句话说，负载配方里的长度分布不是背景参数，而是决定这套方案是否值得部署的第一变量。批大小维度则相反：批不变内核让调度器摆脱了“为数值一致性做特殊排序”的约束，可以自由组批追求吞吐，批形状越不规则、批大小波动越大，这套方案相对“按批大小固定排序”的朴素做法收益越高。</p>\n<p>机制上，可复现性来自归约顺序与 batch 组成解耦。logprob 的计算路径被固定为</p>\n<div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div>\n<p>其中 $z$ 为 logits，固定分块 max 与确定性 reduce 树保证任意 batch size 下同一 token 的 logprob 逐位一致。这条路径要求 rollout 引擎启动时加载批不变内核配置，锁定 attention 的 split-K 因子与 GEMM 的 tile 归约顺序，并在 lm_head 与 softmax 上禁用跨 batch 的动态并行归约。代价随之而来：固定 split-K 因子意味着 SM 占用被钉死，无法按实际 batch 与序列长度弹性分配并行度；确定性 reduce 树在长序列上退化为串行度更高的累加链。工程上应把这条路径视为一条“数值契约”，它换来的是重要性比率 $\\text{ratio}=e^{\\Delta}\\in[1-\\epsilon,1+\\epsilon]$ 稳定落在裁剪阈值内，PPO/GRPO 的组内归一化不再被数值噪声触发。</p>\n<p>负载不对时的失效模式有三类，且彼此叠加。第一类是吞吐预算紧张的长序列 decode 负载：固定归约牺牲的并行度直接转化为时延，若 SLO 以 tokens/s 为主而非可复现性为主，可复现性收益会被速度损失抵消，此时应回退到 stock 内核并把一致性交给高精度重算路径。第二类是适配不完整：批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线对齐，若定制只覆盖了 attention 而漏掉 GEMM 的 tile 归约，或流水线阶段仍按 batch 动态选择归约变体，归约顺序仍会随 batch 变化，逐位一致的前提被悄悄破坏，而这种破坏不会报错，只会表现为 GRPO 组内比较里持续存在的微小概率漂移。第三类是量化路径：与 NVFP4 的兼容需额外验证，若量化内核未保持确定性归约，logprob 逐位一致即告失效。三类失效的共同特征是“静默”——系统仍能跑，吞吐甚至更好，但 off-policy 比率校正与组内比较重新混入数值噪声。因此负载配方的判断标准应写成一张准入表：请求形态为批量 decode、批大小动态、长度分布以中短序列为主、SLO 以可复现性优先，四项同时满足才启用；任一项不满足，就应把确定性路径限制在采样与 logprob 记录环节，训练侧重算走独立的高精度回退。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>适配形态</th><th>不适配时的后果</th></tr></thead><tbody><tr><td>请求形态</td><td>RL rollout 批量 decode，批动态变化</td><td>静态大 batch 预填为主时收益被固定归约开销吃掉</td></tr><tr><td>长度分布</td><td>中短序列，attention 归约占比低</td><td>长序列下速度低于 stock 内核，吞吐预算被抵消</td></tr><tr><td>并发与批大小</td><td>批形状不规则、波动大，调度自由组批</td><td>适配不全时归约顺序仍随 batch 变化，静默破坏一致性</td></tr><tr><td>量化路径</td><td>确定性归约在 NVFP4 下经验证</td><td>量化内核非确定性，logprob 逐位一致前提失效</td></tr></tbody></table>\n<h3 id=\"alg-batch-invariant-rollout-sec-26\">二十六 · 硬件档位：先定确定性预算，再定算力档</h3>\n<p>批不变 Rollout 的部署配方与其他推理场景的排序逻辑相反：先确定“确定性预算”，再选算力档位。原因是固定 split-K 因子与确定性 reduce 树会锁死一部分并行度，算力越高的档位若不配套定制内核，反而可能因为 stock 内核的批相关归约把可复现性丢掉。工程上把 Blackwell 档位分成三档来配：单机 B200/B300 档用于中小规模 RL rollout，要求 attention 与 GEMM 的确定性内核在同一张卡内闭环；GB200/GB300 NVL72 机柜档用于需要大规模并行采样的 GRPO 组内比较，NVLink 5 域内做确定性 all-reduce 的跨卡归约；混合档把 rollout 引擎放在确定性内核已适配的节点上，训练侧重算放在另一批节点，靠 logprob 记录对齐而非靠同卡重算。</p>\n<p>每一档都要回答同一个问题：固定归约顺序带来的吞吐损失是否被可复现性收益覆盖。用公式表达这个权衡，设 stock 内核吞吐为 $T_{\\text{stock}}$，确定性内核吞吐为 $T_{\\text{det}}$，则确定性开销比为</p>\n<div class=\"formula\">$$\\eta_{\\text{det}}=\\frac{T_{\\text{stock}}-T_{\\text{det}}}{T_{\\text{stock}}},\\quad \\text{可接受条件：}\\ \\eta_{\\text{det}}&lt;\\eta_{\\text{budget}}$$</div>\n<p>$\\eta_{\\text{budget}}$ 由 SLO 中吞吐余量决定，材料未给出具体数值，只说明速度略低于 stock 内核。工程判断是：长序列 attention 场景下 $\\eta_{\\text{det}}$ 明显放大，因为固定 split-K 因子限制了跨 SM 的并行归约宽度，此时应把长序列请求路由到确定性内核已充分适配的档位，短序列请求留在高吞吐档位，用请求形态而非统一档位来分摊确定性成本。</p>\n<p>具体例子：一个 GRPO 训练任务，组内 8 条采样需要逐位可比的 logprob。若把 8 条采样分散到 8 个不同 batch 组成的 decode 批次里，stock 内核下同一 prompt 的 logprob 会因 batch size 不同而漂移，组内归一化被数值噪声污染；改用固定 split-K 因子的确定性内核后，8 条采样即使分布在不同批次位置也产出相同概率，裁剪阈值不再被噪声触发。代价是这批 decode 的 token/s 低于 stock 路径，需要用调度参数把这个损失限制在吞吐预算内。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-27\">二十七 · 并行拓扑：确定性归约的域边界</h3>\n<p>并行拓扑的核心约束是“确定性归约不能跨动态变化的并行域”。张量并行（TP）的 all-reduce 若参与方随 batch 变化，归约顺序就随 batch 变化，批不变性被破坏。因此拓扑设计要把确定性归约限制在固定大小的并行组内：TP 组大小固定，组内 all-reduce 用固定顺序的 ring 或 tree 归约；流水并行（PP）的 stage 边界不参与 logprob 归约，只传递 hidden state；数据并行（DP）副本各自独立跑确定性内核，副本间不做 logprob 归约，只做梯度同步。</p>\n<p>伪代码思路如下，描述 rollout 引擎启动时的拓扑绑定：</p>\n<ul>\n<li>读取批不变内核配置，固定 attention 的 split-K 因子 $K_{\\text{fix}}$ 与 GEMM tile 归约顺序；</li>\n<li>把 TP 组大小固定为 $P_{\\text{tp}}$，组内 all-reduce 使用固定顺序，禁止按 batch 动态选择 reduce 算法；</li>\n<li>DP 副本数 $P_{\\text{dp}}$ 可动态伸缩，但每个副本内部必须加载同一版本的确定性内核；</li>\n<li>KV cache 按 TP 组分片，分片规则与 batch 组成无关，避免分片边界随 batch 变化导致 attention 归约顺序漂移。</li>\n</ul>\n<p>系统代价体现在通信带宽上：固定顺序的 TP all-reduce 放弃了按消息大小自适应选择算法的优化，NVLink 5 域内的有效带宽利用率低于自适应路径，跨机柜的 all-reduce 延迟也更刚性。工程判断是：把 TP 组限制在单机 NVLink 域内，跨机柜只做 DP 与 PP，避免确定性归约跨机柜边界，因为跨机柜的归约顺序更难固定且延迟抖动更大。</p>\n<p>具体例子：GB200 NVL72 机柜内 72 个 GPU，若把 TP 组设为 8、DP 组设为 9，则每个 DP 副本内部的确定性内核独立运行，副本间只同步梯度；rollout 采样时同一 prompt 落在哪个 DP 副本不影响 logprob，因为副本内归约顺序固定。若把 TP 组跨机柜扩展到 16，组内 all-reduce 需要跨 NVLink 域，归约顺序的固定成本上升，且跨域延迟抖动会传导到 decode step 的尾延迟。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-28\">二十八 · 量化方案：NVFP4 路径的确定性前置条件</h3>\n<p>NVFP4 量化路径与批不变内核的兼容是本配方里最需要额外验证的一环。材料明确指出：量化路径与 NVFP4 的兼容需额外验证，若量化内核未保持确定性归约，logprob 逐位一致的前提被破坏。工程上的做法是把量化方案分成两层：权重与激活的 NVFP4 量化走已验证的确定性量化内核，量化缩放因子的计算用固定 reduce 树；lm_head 与 softmax 的 logprob 计算路径保持高精度或至少保持确定性归约，不把量化误差引入概率比对的最后一环。</p>\n<p>用公式表达量化对 logprob 偏差的传导，设量化后 logits 为 $\\hat{z}$，量化误差为 $\\delta_q$，则</p>\n<div class=\"formula\">$$\\left|\\log \\hat{p}(a\\mid s)-\\log p(a\\mid s)\\right|\\le \\left\\|\\delta_q\\right\\|_\\infty\\cdot\\left\\|z\\right\\|_\\infty$$</div>\n<p>这个上界说明量化误差本身可以被容忍，前提是误差在 batch 之间一致；一旦量化内核的归约顺序随 batch 变化，$\\delta_q$ 就变成 batch 相关的随机量，上界失效，GRPO 组内比较重新混入噪声。因此量化方案的验收标准不是“量化后精度损失多小”，而是“同一 token 在不同 batch 下量化后的 logits 是否逐位一致”。</p>\n<p>系统代价是显存与带宽：NVFP4 把权重与 KV cache 的位宽压到 4 bit，显存占用与 HBM 带宽需求显著下降，decode 阶段的访存瓶颈缓解；但确定性量化内核的缩放因子归约树固定，量化 kernel 的吞吐低于自适应路径，且需要与 TMA 与 warp-specialized 流水线适配。具体例子：KV cache 用 NVFP4 存储时，attention score 的 max 与 sum 归约必须按固定分块进行，块内顺序与 batch 无关；若量化内核在分块边界上按 batch 动态调整，logprob 的可复现性在长序列下首先失效。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-29\">二十九 · KV 策略：分片规则与 batch 解耦</h3>\n<p>KV 策略在本配方里的约束是“分片规则与 batch 组成解耦”。分页 KV 与分块预填的机制在其他部分已展开，这里只讲它们与批不变性的接口：KV cache 的物理分片边界不能随 batch 变化，否则 attention 的归约顺序会随分片边界漂移。工程做法是把 KV cache 按 TP 组分片，分片大小固定为 $S_{\\text{kv}}$，与 batch size 无关；decode step 的 attention 按固定分块对 score 做 max 与 sum 归约，块内顺序固定。</p>\n<p>伪代码思路：</p>\n<ul>\n<li>KV cache 分配时按 $S_{\\text{kv}}$ 固定分片，分片编号与请求无关，只与 TP 组内位置有关；</li>\n<li>attention 归约按固定块大小 $B_{\\text{attn}}$ 切分，跨块累加顺序固定，块内 max 与 sum 用确定性 reduce 树；</li>\n<li>请求进出批次只改变分片的占用状态，不改变分片的归约顺序；</li>\n<li>长序列请求触发分块预填时，预填阶段的归约同样使用固定分块，避免预填与解码阶段的归约顺序不一致。</li>\n</ul>\n<p>系统代价是显存碎片与带宽：固定分片大小牺牲了按请求长度自适应分配分片的灵活性，短请求会浪费部分分片空间，长请求需要更多分片拼接，拼接处的归约顺序必须固定。HBM 带宽方面，固定分块的 attention 归约在长序列下访存模式更规整，带宽利用率稳定，但并行度受限于固定 split-K 因子。具体例子：一个 batch 里混有 128 token 的短请求与 8K token 的长请求，固定分片下短请求占用一个分片的大部分空间闲置，长请求跨多个分片拼接；若分片边界随 batch 动态调整，长请求的 attention 归约顺序在两次 decode step 之间就可能变化，logprob 不再逐位一致。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-30\">三十 · 调度参数：把确定性成本关进吞吐预算</h3>\n<p>调度参数的设计目标是让批调度器自由组批追求吞吐，同时把确定性内核的成本限制在预算内。材料给出的关键结论是：批调度器在组批时不再需要为数值一致性做特殊排序，可自由追求吞吐。这意味着调度参数可以按纯吞吐目标优化，唯一新增的约束是确定性内核的版本对齐与失败回退。</p>\n<p>参数配方可以写成一组约束：</p>\n<ul>\n<li>批大小 $b$ 动态变化，不设数值一致性相关的排序约束；</li>\n<li>确定性内核版本 $v_{\\text{det}}$ 在 rollout 引擎与训练侧重算侧严格一致，框架升级时同步验证；</li>\n<li>不一致样本按阈值 $\\epsilon_{\\text{det}}$ 标记，回退到高精度路径重算，回退比例计入吞吐预算；</li>\n<li>长序列请求的 split-K 因子固定为 $K_{\\text{fix}}$，短序列请求可用更小的固定因子以保留并行度。</li>\n</ul>\n<p>用公式表达回退比例对有效吞吐的影响，设回退比例为 $r_{\\text{fb}}$，高精度路径吞吐为 $T_{\\text{hp}}$，则有效吞吐为</p>\n<div class=\"formula\">$$T_{\\text{eff}}=(1-r_{\\text{fb}})\\cdot T_{\\text{det}}+r_{\\text{fb}}\\cdot T_{\\text{hp}}$$</div>\n<p>系统代价是尾延迟：回退到高精度路径的样本会拉长单个 decode step 的尾延迟，若回退比例随 batch 组成波动，尾延迟也随之波动。工程判断是把回退阈值 $\\epsilon_{\\text{det}}$ 设为与训练侧裁剪阈值挂钩的量，使回退只发生在真正会触发裁剪的样本上，而不是所有微小偏差样本。具体例子：PPO 的裁剪阈值为 0.2，则 $\\epsilon_{\\text{det}}$ 应显著小于该阈值对应的比率偏差，使回退样本集中在比率偏差接近裁剪边界的少数样本上，回退比例保持在低个位数百分比，有效吞吐接近确定性内核吞吐。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-31\">三十一 · 可复现配置思路：从内核版本到验收口径</h3>\n<p>把上述五节收拢成一条可复现的配置路径，核心是三个固定与一个验收：固定 split-K 因子、固定 reduce 树、固定分块 softmax max，验收口径是同一 token 在不同 batch size 下 logprob 逐位一致。配置顺序如下：</p>\n<ul>\n<li>先在内核层固定 $K_{\\text{fix}}$ 与 $B_{\\text{attn}}$，在单卡上验证同一 prompt 在 batch size 1 与 batch size $b$ 下 logprob 逐位一致；</li>\n<li>再在拓扑层固定 TP 组大小与组内 all-reduce 顺序，验证跨 DP 副本的 logprob 一致性；</li>\n<li>再在量化层验证 NVFP4 量化内核的归约确定性，若量化内核未保持确定性归约，则 lm_head 与 softmax 路径退回高精度确定性内核；</li>\n<li>最后在调度层放开组批约束，用回退比例与有效吞吐验收，确认确定性成本落在吞吐预算内。</li>\n</ul>\n<p>这条路径的工程判断是：批不变 Rollout 的部署不是“选最快硬件 + 开确定性开关”，而是把确定性当作一等资源来分配。固定归约顺序放弃的并行度是显式成本，必须用请求形态路由、TP 域边界、量化分层来分摊；任何一层适配不完整，归约顺序仍可能随 batch 变化，GRPO 组内比较重新混入数值噪声。验收时不要只看平均吞吐，要看同一 token 在 batch size 扫描下的 logprob 逐位一致性，以及在长序列 attention 下确定性内核相对 stock 内核的吞吐损失是否仍在预算内。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-32\">三十二 · 批不变内核的部署边界：什么时候值得为确定性付这笔账</h3>\n<p>这套配方的核心不是“把 kernel 写死”，而是把归约顺序从“由 batch 组成决定”改成“由编译期常量决定”。rollout 引擎启动时加载批不变内核配置：attention 的 split-K 因子固定为常量 $S$，GEMM 的 tile 归约顺序固定，decode 每个 step 对 attention score 按固定分块做 max 与 sum 归约，块内顺序与 batch 无关；lm_head 与 softmax 走确定性 reduce 树，禁止跨 batch 的动态并行归约。于是 logprob 的计算退化为 <div class=\"formula\">$$\\log p(a\\mid s)=\\mathrm{ReduceTree}_{\\mathrm{fixed}}\\big(\\mathrm{softmax}_{\\mathrm{chunk}}(z)\\big),\\quad \\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$$</div> 其中 $z$ 为 logits。这个式子的工程含义是：只要 $S$ 与分块大小不变，同一 prompt 在 batch=1 与 batch=64 下产出的 logprob 逐位一致，训练侧重算时用同一确定性 kernel 即可让重要性比率落在 $[1-\\epsilon,1+\\epsilon]$ 内，PPO/GRPO 的裁剪阈值不再被数值噪声触发。</p>\n<p>代价集中在并行度上。固定 split-K 因子等于放弃了按 batch 与序列长度自适应选择 split-K 变体的自由，长序列 attention 下 SM 占用率与 stock 内核相比有可测的差距，吞吐损失随序列长度放大。这不是可以靠调参抹平的——它是确定性的定义性成本。因此部署配方要先回答一个问题：这条 rollout 路径的瓶颈是吞吐还是比率可信度。若 SLO 以 logprob 可复现性与 GRPO 组内比较为主、吞吐有富余，批不变内核应当作为默认路径；若吞吐预算紧张且序列偏长，可复现性收益会被 kernel 性能损失抵消，此时应把确定性路径限制在需要严格比率的样本上（例如组内比较与 off-policy 校正的关键 token），其余走 stock 内核并接受 $\\epsilon_{\\text{det}}$ 的统计容忍。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>确定性路径</th><th>stock 路径</th></tr></thead><tbody><tr><td>split-K 因子</td><td>固定常量，编译期确定</td><td>按形状自适应</td></tr><tr><td>softmax 归约</td><td>确定性 reduce 树 + 固定分块 max</td><td>批相关动态归约</td></tr><tr><td>长序列吞吐</td><td>低于 stock，随长度放大</td><td>较高</td></tr><tr><td>logprob 一致性</td><td>任意 batch 逐位一致</td><td>随 batch 组成漂移</td></tr></tbody></table>\n<p>失效条件有三类，必须在部署前逐条验证。其一，适配不完整：批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线对齐，若流水线阶段划分仍按 batch 动态调整，归约顺序会重新随 batch 变化，逐位一致的前提静默失效——这类问题不会报错，只会表现为比率分布的缓慢漂移，需用固定 prompt 在不同 batch 下做逐位比对作为上线门禁。其二，量化路径破坏确定性：NVFP4 量化本身处理的是量化误差导致的分布偏移，与本题的归约顺序问题是两回事；若 NVFP4 内核未保持确定性归约，logprob 逐位一致的前提被破坏，GRPO 组内比较仍混入数值噪声，因此量化方案与批不变内核的兼容需额外验证，不能假定二者正交。其三，版本漂移：确定性路径要求 rollout 侧与训练侧 kernel 版本严格对齐，框架升级时需同步验证两侧重算结果，否则 $\\Delta$ 的来源从数值噪声变成版本差异，比率校正失去意义。硬件档位、并行拓扑与 KV 配置在本方案中不承担一致性职责，可自由按吞吐与显存预算选取，这正是批不变内核换来的调度自由度。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-33\">三十三 · 固定归约在SM100上的真实开销：并行度换确定性</h3>\n<p>批不变内核的代价不是抽象的“略慢”，而是可以拆到具体硬件资源上的三笔账。第一笔是split-K因子被钉死。Blackwell的tcgen05 MMA在2-SM模式下做GEMM时，K维切分数量直接决定SM占用与TMEM分配；stock内核会按当前batch形状动态选split-K，短序列用小split换低延迟，长序列用大split换吞吐。批不变路径把split-K写成编译期常量，于是同一份kernel在batch=1与batch=64时都走同一套归约树，K维并行度不再随负载伸缩。第二笔是attention score的max与sum归约被固定分块，块内顺序与batch无关，跨块累加顺序也固定，这意味着warp-specialized流水线里负责跨块累加的warp不能按占用率动态重组。第三笔是softmax与lm_head的确定性reduce树，禁止跨batch的动态并行归约，原本可以借batch维做并行归约的softmax被迫退化为逐行固定树。</p>\n<p>三笔账合起来，量化到系统指标上：长序列decode阶段attention占主导时，固定split-K使SM占用率下降，单token延迟上升；短序列或小batch时损失相对小，因为并行度本来就不饱和。吞吐侧的表现是，batch越大，stock内核越能靠split-K把K维填满，批不变内核的吞吐差距越明显。显存侧影响较小，但TMEM分配因固定分块而失去弹性，2-SM MMA的TMEM预算在固定tile下可能留出无法利用的空隙。功耗侧则出现一个反直觉现象：固定归约让部分SM在长序列下空转等待跨块累加，SM利用率下降但时钟不一定降，单位token能耗反而变差。</p>\n<div class=\"formula\">$$\\text{cost}_{\\text{det}}=\\underbrace{T_{\\text{fixed-splitK}}-T_{\\text{stock}}}_{\\text{延迟}}+\\underbrace{\\Delta\\text{SM-occ}\\cdot f_{\\text{clk}}}_{\\text{吞吐}}+\\underbrace{\\Delta\\text{TMEM-frag}}_{\\text{显存碎片}}$$</div>\n<p>具体例子：一个RL rollout引擎在GB200 NVL72单节点上跑批量decode，序列长度落在长上下文区间时，attention的K维归约成为主路径，固定split-K因子使每SM的K切片数少于stock动态选择的结果，跨块累加warp成为串行瓶颈。此时若调度器为了追吞吐把batch从16拉到64，stock内核能靠更大split-K吸收新增并行度，批不变内核吸收不了，吞吐曲线提前走平。这就是“规模上去以后哪里先崩”的第一个答案：不是显存先崩，是长序列下的K维并行度先崩。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-34\">三十四 · 显存与KV带宽：确定性路径不改变容量，但改变访问节律</h3>\n<p>批不变内核本身不增加KV cache容量需求，分页KV的块分配逻辑与batch组成无关，这部分容量账由分页KV批量Rollout那条线承担，此处只指路。但确定性归约改变了KV的访问节律，进而影响有效带宽。固定分块attention要求每个decode step按固定块大小读取KV，块边界不随batch形状浮动，于是TMA的批量传输描述符可以预编排、跨step复用，这是收益面：KV读取的TMA事务更规整，L2命中模式更稳定。代价面是，当batch组成变化导致某些请求提前结束、分页块被回收时，固定分块读取无法像stock内核那样按剩余batch动态收缩块大小，尾部step会出现读放大——按固定块读进来的KV里有一部分属于已完成的请求，被归约树白白消费。</p>\n<p>带宽账要分两层看。HBM侧，固定分块让每次TMA传输的粒度恒定，避免了stock内核在小batch尾部step的碎片化小传输，HBM有效带宽利用率在稳态段更好。L2侧，确定性reduce树要求跨块累加按固定顺序进行，这意味着中间累加结果不能在L2里随意重排，L2驻留的partial sum缓冲区大小被固定分块锁定，不能按batch弹性伸缩。当batch远大于固定分块设计点时，partial sum缓冲区成为L2压力源，挤占KV的L2驻留空间，KV读取回落到HBM，有效带宽下降。</p>\n<ul>\n<li>机制：TMA描述符预编排 + 固定块KV读取，稳态段事务规整。</li>\n<li>代价：尾部step读放大，partial sum缓冲区锁定L2占用。</li>\n<li>指标：HBM有效带宽稳态改善、尾段下降；L2驻留KV比例随batch增大而压缩。</li>\n<li>例子：batch=64稳态段KV读取走TMA大批量，尾段只剩3个活跃请求时仍按64请求的固定块读，读放大比例随尾段长度线性上升。</li>\n</ul>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-35\">三十五 · 通信：确定性kernel与集合通信的耦合点</h3>\n<p>在NVL72这种72 GPU单NVLink域的拓扑上，rollout的通信代价主要不在张量并行AllReduce，而在分离式预填/解码之间的KV传输与NIXL的点对点搬运——这部分由分离式预填解码rollout那条线展开，此处只讲与本算法耦合的部分。批不变内核与通信的耦合点有两个。其一是确定性reduce树与TP归约的叠加：如果rollout引擎同时开张量并行，attention的跨块累加是确定性的，但TP的AllReduce若使用NVLS或ring算法，其归约顺序随rank数与消息大小变化，会把确定性重新打散。要让端到端logprob逐位一致，TP归约也必须固定算法与分段，这等于把集合通信的算法选择也钉死，牺牲了NCCL按拓扑动态选算法的能力。</p>\n<p>其二是分离式架构下的重算对齐：训练侧重算logprob时，若rollout与训练跑在不同并行拓扑上（比如rollout用2-SM MMA的TP=2，训练用TP=4），确定性kernel的固定分块必须在两种拓扑下产出相同归约顺序，否则比特级对齐破裂。这要求固定分块大小与split-K因子在拓扑间可映射，映射不完整时归约顺序仍随batch与rank变化——这正是失败模式里“适配不完整”的具体形态。通信代价因此表现为：为了保确定性，集合通信算法被固定，NCCL无法按消息大小切换，小消息走ring而非tree，AllReduce延迟上升；跨拓扑重算需要额外的对齐验证，部署复杂度上升。</p>\n<div class=\"formula\">$$\\text{order}_{\\text{e2e}}=\\text{ReduceTree}_{\\text{fixed}}\\circ\\text{AllReduce}_{\\text{fixed-alg}},\\quad \\text{alg}\\notin\\text{NCCL-dynamic}$$</div>\n<p>例子：GB200 NVL72上rollout用TP=2、训练用TP=4，固定分块在TP=2下每SM处理K/2，在TP=4下每SM处理K/4，若分块大小不随拓扑整除映射，跨块累加边界错位，同一token的logprob在两侧不一致，GRPO组内比较重新混入噪声。工程判断是：拓扑映射必须在部署配方里显式约束，不能留给运行时自适应。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-36\">三十六 · 尾延迟：固定分块在batch收缩时的刚性</h3>\n<p>尾延迟是本算法最容易被低估的系统代价。连续批处理下batch组成持续变化，一个长请求可能横跨数十个decode step，其间同批的其他请求陆续完成，活跃batch从64缩到个位数。stock内核在batch收缩时会重选split-K、缩小分块、释放SM，尾段step的延迟随之下降。批不变内核不能这么做：固定分块与固定split-K是为设计点batch准备的，batch收缩后归约树照旧执行，跨块累加的warp数不变，SM占用不变，于是尾段每个step的延迟与满batch时几乎相同。对SLO而言，这意味着p99延迟被尾段step钉在高位，而不是随batch收缩自然回落。</p>\n<p>更细的机制是：确定性reduce树的跨块累加是串行链，块数固定，链长固定，尾段step的critical path不缩短。stock内核可以用split-K把长链拆成并行短链再合并，批不变内核禁止这种动态拆分。尾延迟的放大倍数取决于固定块数与实际活跃请求数的比值——比值越大，空转的归约工作越多。功耗侧同步恶化：尾段step SM占用不变但有效计算量骤降，单位token能耗在尾段抬升，对功耗预算紧张的部署点是实打实的成本。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>活跃batch</th><th>归约工作量</th><th>尾延迟形态</th></tr></thead><tbody><tr><td>稳态</td><td>64</td><td>满</td><td>正常</td></tr><tr><td>收缩中</td><td>32</td><td>固定块，半空转</td><td>延迟不降</td></tr><tr><td>尾段</td><td>4</td><td>固定块，大量空转</td><td>p99被钉高</td></tr></tbody></table>\n<p>例子：一个GRPO训练步的rollout批次里，最长序列比中位数长数倍，尾段只剩少数请求在decode，批不变内核仍按设计点分块执行归约，尾段每step延迟与满batch持平，整批rollout的完成时间由尾段决定，吞吐收益被尾延迟吃掉。工程上的缓解不是改kernel，而是调度层把长请求与短请求分组、让尾段尽量同质，这属于负载配方范畴，但代价的根源在kernel刚性。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-37\">三十七 · 规模上去以后哪里先崩：四条曲线的交叉点</h3>\n<p>把显存、带宽、通信、功耗、尾延迟放在同一坐标系里看，规模上升时它们不是同时崩，而是按顺序暴露。第一崩的是长序列下的K维并行度：序列长度先于batch规模触顶，固定split-K在长上下文attention上先失去SM占用，吞吐曲线走平。第二崩的是尾延迟：batch规模上去后尾段step的绝对延迟不变，但它在总完成时间里的占比随batch增大而上升，p99先于p50恶化。第三崩的是通信耦合：跨节点或跨拓扑部署时，TP归约算法被固定，NCCL动态选路失效，AllReduce延迟在消息变小的时候先恶化。第四崩的才是显存与功耗：partial sum缓冲区锁定L2、TMEM碎片、尾段空转抬能耗，这些是规模到一定程度后的次生代价。</p>\n<p>这个排序的工程含义是：扩容时不要先加batch，先确认序列长度分布是否落在固定分块的设计区间内；不要先加TP，先确认rollout与训练的拓扑映射是否整除；不要先追峰值吞吐，先看尾段活跃batch的分布。批不变内核的吞吐损失在稳态段可测但不致命，真正让SLO失守的是尾段刚性与拓扑映射破裂。判断一个部署点是否适合开批不变内核，看的不是平均吞吐，而是长序列占比、尾段batch分布、以及rollout与训练拓扑是否同构——三者任一不满足，可复现性收益会被系统代价抵消。</p>\n<div class=\"formula\">$$\\text{break-order}:\\ \\text{K-parallel}\\prec\\text{tail-latency}\\prec\\text{comm-coupling}\\prec\\text{mem/power}$$</div>\n<p>具体机制上，尾段刚性的根源是固定块数与活跃请求数解耦，缓解只能靠调度层做尾段同质化分组；拓扑映射破裂的根源是固定分块大小不随TP整除，缓解只能靠部署时约束拓扑或预生成映射表。这两条都不是kernel内部能解决的，属于系统层判断。规模上去以后先崩的是并行度与尾延迟，显存和功耗是后置代价——这个顺序决定了容量规划应该先压序列长度方差，再压尾段batch方差。</p>\n\n\n<h3 id=\"alg-batch-invariant-rollout-sec-38\">三十八 · 确定性内核的吞吐税：固定 split-K 与 TMA 流水线的冲突点</h3>\n<p>批不变内核的代价不是均匀摊在整条推理链上的，它集中在 attention 的 split-K 归约与 GEMM 的 tile 归约两处。stock 实现会根据当前 batch 组成动态选择 split-K 因子：批小、序列长时切更多 K 段以填满 SM；批大时收窄切分以避免跨段累加的额外带宽。批不变路径把因子钉死，等于放弃了这条随负载自适应调节并行度的通路。在 Blackwell 上这层损失会被 TMA 与 warp-specialized 流水线放大——固定分块意味着 producer warp 的 TMA 拷贝粒度、consumer warp 的 MMA 消费节奏都必须按最坏情况预留，流水线深度不能随 batch 伸缩，SM 占用率在批形状偏离设计点时下滑。代价可写成对有效算力的折损：</p>\n<div class=\"formula\">$$\\text{throughput}_{\\text{det}} = \\text{throughput}_{\\text{stock}}\\cdot\\eta_{\\text{fix}},\\quad \\eta_{\\text{fix}} = \\frac{T_{\\text{pipe}}}{T_{\\text{pipe}}+\\tau_{\\text{tail}}}$$</div>\n<p>其中 $\\tau_{\\text{tail}}$ 是固定分块在尾块上无法被其他 CTA 填充的空转时间，长序列 attention 下这一项随序列长度增长而变重，是吞吐最先崩的位置。工程判断很直接：短序列、大批的 decode 阶段损失可控；一旦上下文拉到长序列、批被 KV 显存压小，固定 split-K 的空转占比上升，可复现性收益开始被吞吐预算抵消。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-39\">三十九 · NVFP4 路径上的确定性缺口与逐位一致的脆弱前提</h3>\n<p>公式 $\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right| \\le \\epsilon_{\\text{det}}$ 成立的前提是两侧走同一条确定性归约树，而 NVFP4 量化路径恰好是这条前提最易断裂的地方。量化内核若在反量化后按 batch 相关的分块做累加，或为了吞吐启用随批形状切换的 reduce 变体，logprob 的逐位一致立刻失效，GRPO 组内归一化重新混入数值噪声，裁剪阈值被误触发。这不是精度问题而是顺序问题：NVFP4 的 scale 因子布局与 tile 切分耦合，量化 kernel 的归约顺序往往由 tile 形状隐式决定，批不变配置必须显式锁住这条链路，兼容性需逐版本验证而非默认继承。</p>\n<table class=\"mini\"><thead><tr><th>代价维度</th><th>批不变路径的表现</th><th>先崩的位置</th></tr></thead><tbody><tr><td>显存</td><td>与 stock 同量级，KV 配置不受影响</td><td>非瓶颈</td></tr><tr><td>带宽</td><td>固定分块跨段累加带来额外读写</td><td>长序列 attention 的 K/V 重读</td></tr><tr><td>通信</td><td>组批自由，不引入额外集合通信</td><td>非瓶颈</td></tr><tr><td>尾延迟</td><td>尾块无法被异构 CTA 填充</td><td>批形状偏离设计点时最先劣化</td></tr></tbody></table>\n<p>规模上去以后先崩的是尾延迟而非平均吞吐：固定归约让调度器失去了用异构批形状填缝的手段，P99 在批组成抖动时被拉长。功耗层面，确定性路径避免了为数值一致性做的特殊排序与重算回退，稳态功耗反而更可预测；但一旦触发阈值回退到高精度重算，瞬时功耗与延迟同时抬升。真正的边界条件是定制成本——批不变内核需与 TMA、warp-specialized 流水线逐层对齐，适配不完整时归约顺序仍会随 batch 漂移，此时既付了吞吐税又没拿到可复现性。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-40\">四十 · 精度漂移的三种来源与可观测判据</h3>\n<p>批不变内核承诺的是 logprob 逐位一致，破坏这个承诺的路径有三条，诊断时必须分开归因，否则回滚会打错补丁。第一条是归约树本身没锁死：attention 的 split-K 因子在长序列下被启发式调度器改写，或 GEMM tile 归约顺序随 M 维（即 batch 维）变化，此时同一 token 在不同批位置上的 logits 差异落在 1e-3 量级，重要性比率 $e^{\\Delta}$ 抖动明显。第二条是量化路径旁路：NVFP4 的 scale 计算若走批相关的 amax 归约，量化内核的确定性前提被打破，误差从 1e-3 跳到 1e-2 量级，且表现为与 batch 组成强相关的系统性偏移而非随机噪声。第三条是 kernel 版本错配：rollout 侧与训练侧重算用了不同的确定性内核版本，归约分块大小不一致，误差稳定存在但不随批变化——这类最容易被误判成“模型本身分布偏移”。</p>\n<p>判据用前文公式直接落地：对同一 prompt 构造两组不同批组成的 rollout，逐 token 比较 $\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right|$，把差值按 token 位置分桶。若差值集中在序列尾部且随 batch size 单调增长，指向 split-K 因子漂移；若差值在整个序列上均匀且量级偏大，指向量化归约旁路；若差值恒定且与批无关，指向版本错配。监控上不需要全量比对，按固定比例抽样重算即可，抽样成本是每样本一次前向重算，在 decode 主导的负载里占比可控。</p>\n<div class=\"formula\">$$\\Delta_i=\\log p_{\\text{rollout}}(y_i|x)-\\log p_{\\text{train}}(y_i|x),\\quad \\text{flag}=\\mathbb{1}\\left[\\max_i|\\Delta_i|&gt;\\epsilon_{\\text{det}}\\right]$$</div>\n<p>工程代价在于：抽样重算占用训练侧算力，若抽样率过高会挤占梯度计算；阈值 $\\epsilon_{\\text{det}}$ 设得过紧会把正常的浮点末位差异全部标红，设得过松则漏掉量化旁路。实践上按 token 位置分桶后再定阈值，比全局单阈值更能区分三类来源。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-41\">四十一 · OOM 的三条隐蔽通道</h3>\n<p>批不变 Rollout 的显存失败很少来自“批太大”这种显式原因，更多是三条隐蔽通道。其一，确定性 reduce 树为了固定顺序，往往需要保留中间归约缓冲而不能原地累加，长序列 attention 下这块缓冲随序列长度线性增长，在 KV cache 已经吃满显存的 decode 阶段成为压垮点。其二，logprob 记录路径要求采样时把 token 与对应 logprob 一并落盘或驻留，若按批累积而不及时 flush，记录缓冲会与 KV 争抢同一块 HBM。其三，回退到高精度路径重算不一致样本时，高精度 kernel 的临时张量尺寸通常大于 NVFP4 路径，瞬时峰值出现在重算窗口内，表现为周期性 OOM 而非持续 OOM。</p>\n<p>诊断靠显存时间线而非单点峰值：把 decode step 的显存占用按 step 打点，若峰值出现在 logprob flush 或重算窗口，即可定位通道。缓解手段是给记录缓冲设硬上限并按 step 异步 flush，给重算窗口预留固定显存配额，而不是让重算与正常 decode 共享弹性池。代价是 flush 引入额外的主机侧拷贝与同步点，在尾延迟敏感的负载里要把 flush 挪到批边界而非 step 中间。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-42\">四十二 · 批抖动与路由不均的耦合</h3>\n<p>批不变内核让调度器可以自由组批追求吞吐，副作用是批形状变化更剧烈，批抖动被放大。抖动本身不破坏数值一致性，但会破坏两个系统指标：一是 decode step 的延迟方差，批大小在相邻 step 间跳变导致 kernel 启动配置反复重编译或重选，SM 占用率出现锯齿；二是分离式部署下预填与解码实例之间的路由不均，若路由器按请求数而非按 token 数或 KV 占用分配，短请求扎堆到同一解码实例，该实例批大小虚高而其他实例空转。</p>\n<p>监控批抖动用相邻 step 批大小的相对变化率，监控路由不均用各实例的 KV 占用方差与批大小方差之比。判据是：若批大小方差高而 KV 占用方差低，问题在组批策略；若两者同时高，问题在路由权重。修复路由不均的机制是把分配权重从请求计数改为预估 token 数乘以 KV 页数，代价是路由器需要读取请求的长度先验，对未知长度的请求退化为保守估计，可能造成短请求的轻微排队。</p>\n<table class=\"mini\"><thead><tr><th>现象</th><th>指向</th><th>处置</th></tr></thead><tbody><tr><td>批大小锯齿、延迟方差上升</td><td>组批策略过于激进</td><td>给批大小变化率设上限</td></tr><tr><td>单实例 KV 占用高、其他空转</td><td>路由按请求数分配</td><td>改为 token×KV 页加权</td></tr><tr><td>重算窗口周期性 OOM</td><td>高精度回退无配额</td><td>预留固定显存、错峰重算</td></tr></tbody></table>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-43\">四十三 · 尾延迟尖刺的定位顺序</h3>\n<p>尾延迟尖刺在批不变 Rollout 里有固定的排查顺序，因为确定性内核把一部分抖动源消除了，剩下的尖刺更容易归因。先看是否与 logprob 抽样重算窗口重合：重算走的是训练侧 kernel，其启动与同步语义与推理侧不同，若与 decode 同卡共存会拉长个别 step。再看是否与 KV 页分配的长尾重合：批形状剧烈变化时，分页 KV 的页申请可能触发碎片整理，整理期间新请求被阻塞。最后看是否与 NCCL 集合通信的批边界对齐：分离式部署下预填实例向解码实例传 KV 的时机若与 decode step 不对齐，个别 step 会等待传输完成。</p>\n<p>定位手段是在 step 级打三个时间戳：kernel 启动、KV 页分配完成、KV 传输完成，三者中偏离中位数最大的那一段即为尖刺来源。代价是打点本身引入同步开销，只应在诊断窗口内开启，常态监控用聚合直方图而非逐 step 打点。修复顺序上优先错峰重算窗口，其次给 KV 页分配预留空闲页池，最后调整传输时机与 decode step 对齐。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-44\">四十四 · 回滚的分级与版本对齐</h3>\n<p>回滚不是单一动作，按失败模式分三级。一级回滚只关掉抽样重算与高精度回退，保留批不变内核，适用于重算窗口引发的 OOM 与尾延迟尖刺，代价是不一致样本不再被标记，重要性比率噪声重新进入训练，但数值一致性主体仍在。二级回滚把确定性内核换回 stock 内核，适用于归约树漂移或量化旁路无法在当版修复的情况，代价是放弃可复现性、调度器重新需要为数值一致性做特殊排序，吞吐与批自由度同时下降。三级回滚是框架版本整体回退，适用于 rollout 与训练侧 kernel 版本错配且无法单侧对齐，代价最大但能恢复比特级一致。</p>\n<p>回滚的判据必须可自动触发：以抽样重算的标记率为输入，标记率超过阈值并持续若干窗口即触发一级回滚；若一级回滚后标记率不降，说明问题不在重算窗口而在内核本身，升级到二级。版本对齐是二级与三级之间的关键约束——确定性路径要求 rollout 与训练侧 kernel 版本严格一致，框架升级时必须同步验证两侧的归约分块与 split-K 因子，验证方式是固定输入跑两侧重算比对逐位结果，而不是比对统计分布。</p>\n<p>工程判断落在最后这一步：批不变 Rollout 的稳定性收益来自比特级对齐，而比特级对齐的维护成本主要不在 kernel 本身，在版本同步与回滚链路的自动化。把抽样重算的标记率做成一级监控指标、把两侧 kernel 版本做成部署清单里的硬约束，比在单次故障后手工比对 logprob 更能守住这条确定性路径。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-45\">四十五 · 批不变内核的失效面：从逐位一致到逐位漂移</h3>\n<p>批不变内核的承诺是「同一 token 在任意 batch size 下 logprob 逐位一致」，但这个承诺有三条明确的断裂线，每一条都会让重要性比率重新漂离 1。第一条是适配不完整：内核必须与 Blackwell 的 TMA 与 warp-specialized 流水线对齐，若某个 attention 变体仍走动态 split-K，或 GEMM 的 tile 归约顺序在尾块上随 batch 余数变化，则固定分块只覆盖了主路径，余数路径仍带批相关性。诊断方式是构造探针：同一 prompt 分别以 batch=1、奇数 batch、满载 batch 各跑一次，逐 token 比对 logprob 的比特模式，任何一位差异即定位到未固定的归约点。第二条是量化路径：NVFP4 的 scale 计算与反量化若引入批相关的分组归约，logprob 逐位一致的前提被直接破坏，GRPO 组内比较仍混入数值噪声，且这种噪声与量化误差耦合，比纯归约噪声更难归因。第三条是版本漂移：确定性路径要求 rollout 侧与训练侧重算侧使用严格对齐的 kernel 版本，框架升级时若只升一侧，两边的归约树结构不同，比率会系统性偏移。</p>\n<p>监控指标应直接建在比率分布上，而不是建在吞吐上。对每个训练 step 收集 rollout 记录的 logprob 与训练侧重算的 logprob，计算</p>\n<div class=\"formula\">$$\\Delta_i=\\log p_{\\text{rollout}}(y_i|x)-\\log p_{\\text{train}}(y_i|x),\\qquad \\text{ratio}_i=e^{\\Delta_i}$$</div>\n<p>并统计 $\\max_i|\\Delta_i|$、$\\Delta$ 的方差以及落在 $[1-\\epsilon,1+\\epsilon]$ 之外的样本比例。批不变内核正常工作时 $\\Delta$ 应集中在零附近且方差极小；一旦某个 batch 形状触发未固定的归约分支，$\\Delta$ 的方差会在该形状上出现尖峰，而均值仍接近零——这正是「批抖动」的指纹，它与路由不均造成的负载倾斜是两回事。工程上把 $\\max|\\Delta|$ 超过 $\\epsilon_{\\text{det}}$ 的样本标记出来，回退到高精度路径（FP32 归约或非量化 kernel）重算该样本的 logprob，再进入 PPO/GRPO 的裁剪与组内归一化；回退比例本身是健康度指标，持续上升说明确定性路径已与训练侧脱节。</p>\n<p>尾延迟尖刺与 OOM 在本方案里有独立成因。固定 split-K 因子与确定性 reduce 树牺牲了部分并行度，长序列 attention 下速度低于 stock 内核，序列长度分布的尾部会把这一损失放大成 decode 阶段的尾延迟尖刺；若调度器为追吞吐而放大批，KV cache 与激活的峰值显存随之抬升，OOM 往往先出现在长序列与大批叠加的那一档。批抖动还会伪装成路由不均：组批不再为数值一致性做特殊排序后，调度器自由追求吞吐，某些 expert 或某些 DP rank 收到的 token 数偏斜，表现为个别 rank 的 step 时间拉长，而根因可能是该 rank 上恰好命中了未固定的归约分支。区分办法是同时看 $\\Delta$ 方差与 rank 级 step 时间：前者尖峰指向数值路径，后者尖峰指向负载。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首选判据</th><th>处置</th></tr></thead><tbody><tr><td>比率系统性偏离 1</td><td>$\\Delta$ 均值非零</td><td>核对两侧 kernel 版本，同步升级</td></tr><tr><td>特定 batch 形状方差尖峰</td><td>按 batch size 分桶的 $\\Delta$ 方差</td><td>定位未固定的 split-K 或尾块归约</td></tr><tr><td>长序列尾延迟</td><td>序列长度分位与 step 时间</td><td>限制批内长序列占比或降 split-K 并行</td></tr><tr><td>单 rank 时间拉长</td><td>$\\Delta$ 方差与 rank 时间联看</td><td>区分数值分支与路由偏斜</td></tr></tbody></table>\n<p>回滚必须按层做，而不是整栈回退。第一层是样本级：超阈值样本走高精度重算，代价是少量额外算力，不影响吞吐大盘。第二层是内核级：将 rollout 侧切回 stock 内核并接受概率漂移，此时必须同步放大 $\\epsilon$ 或改用更保守的裁剪，否则数值噪声会持续触发裁剪、浪费 on-policy 样本。第三层是调度级：恢复为数值一致性做特殊排序的组批策略，牺牲批形状自由度换可复现性。三层回滚的触发条件应绑定在 $\\max|\\Delta|$ 与回退比例的联合阈值上，而不是单看延迟；因为固定归约带来的吞吐损失是可预期的常量，而数值漂移是随 batch 组成随机出现的变量，后者对训练信号的污染远大于前者对吞吐的侵蚀。</p>\n<h3 id=\"alg-batch-invariant-rollout-sec-46\">四十六 · 对照的坐标系：误差来源决定算法归属</h3>\n<p>把批不变 Rollout 放到同族算法里比较，先要建立一个坐标系，而不是按名字排优先级。这个坐标系的原点是“on-policy 数据与训练侧重算之间的偏差从哪来”。批不变内核处理的是<strong>归约顺序</strong>这一类误差：attention 的 split-K 因子、GEMM 的 tile 累加次序、softmax 的 max/sum 归约树，只要其中任一环节随 batch 组成变化，同一 prompt 的 logprob 就不可复现。NVFP4 量化稳定化处理的是<strong>数值表示</strong>这一类误差：低精度尾数截断与 scale 选择带来的分布偏移，即使归约完全确定也依然存在。异步权重同步处理的是<strong>时间维度</strong>的误差：rollout 引擎持有的策略版本落后于训练侧，产生 staleness。三者可以叠加，但不能互相替代——固定了归约顺序并不能消除量化误差，提高了量化精度也不能让 split-K 的批相关性消失。</p>\n<p>因此选型的第一问不是“哪个算法更强”，而是“我的偏差预算里，哪一项占主导”。判别式可以写成对重要性比率上界的分解：</p>\n<div class=\"formula\">$$\\left|\\log p_{\\text{rollout}}(y|x) - \\log p_{\\text{train}}(y|x)\\right| \\le \\epsilon_{\\text{det}} + \\epsilon_{\\text{quant}} + \\epsilon_{\\text{stale}},\\quad \\text{ratio}=e^{\\Delta}\\in[1-\\epsilon,1+\\epsilon]$$</div>\n<p>三项分别对应确定性内核、量化路径、权重版本。工程判断的落点是：如果 $\\epsilon_{\\text{det}}$ 已经让 ratio 越过 PPO 的裁剪阈值，那么先上批不变内核；如果 $\\epsilon_{\\text{det}}$ 远小于 $\\epsilon_{\\text{quant}}$，定制确定性内核的收益会被量化噪声淹没，属于把预算花在错误的地方。这个分解也解释了为什么批不变内核的失败模式里专门提到 NVFP4：量化内核若未保持确定性归约，逐位一致的前提就被破坏，GRPO 组内比较仍混入噪声。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-47\">四十七 · 决策表：五个维度的取舍</h3>\n<p>下表把批不变 Rollout 与相邻算法放在同一组判据下对照。判据选取的是工程上真正会改变决策的维度，而不是架构参数。</p>\n<table class=\"mini\"><thead><tr><th>判据</th><th>批不变 Rollout</th><th>NVFP4 量化稳定化</th><th>异步 Rollout 流水线</th><th>特征级投机采样</th></tr></thead><tbody>\n<tr><td>消除的误差源</td><td>归约顺序 / batch 组成</td><td>低精度表示与 scale</td><td>策略版本 staleness</td><td>草稿模型与目标模型分布差</td></tr>\n<tr><td>是否改变 kernel 数值路径</td><td>是，固定 split-K 与 reduce 树</td><td>是，量化/反量化路径</td><td>否，改调度与权重同步节奏</td><td>否，改采样流程</td></tr>\n<tr><td>主要代价</td><td>放弃 split-K 并行度，长序列吞吐下降</td><td>精度校验与回退路径</td><td>staleness 需比率校正兜底</td><td>验证开销与接受率不足时的空转</td></tr>\n<tr><td>与训练侧耦合强度</td><td>高，kernel 版本须严格对齐</td><td>中，量化配置须一致</td><td>低，只需版本号与校正公式</td><td>低，草稿模型可独立替换</td></tr>\n<tr><td>典型触发条件</td><td>GRPO 组内比较被噪声污染、ratio 频繁越界</td><td>显存/带宽受限且精度可校验</td><td>预填与解码资源争抢、吞吐不饱和</td><td>解码受内存带宽限制、序列可预测</td></tr>\n</tbody></table>\n<p>读表的方式是逐行排除：若第一行指认的误差源不是你观测到的主导项，该列算法就不该进候选集。举例来说，一个 GRPO 训练任务若发现同一组内八个样本的奖励归一化后方差异常大，且把 batch size 固定成常量后方差显著收敛，这就是归约顺序主导的典型信号，应优先批不变内核；反之若固定 batch size 后方差不变，而降低量化位宽后方差跳变，则主导项在量化列。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-48\">四十八 · 与量化路径的共存条件</h3>\n<p>批不变内核与 NVFP4 不是互斥关系，但共存有硬条件：量化内核本身必须使用确定性归约。伪代码层面的检查点是，反量化后的 GEMM 累加是否仍走固定 tile 顺序、softmax 的 max 归约是否在量化域内保持固定分块。若量化 kernel 为了吞吐在 scale 计算中引入了批相关的动态并行归约，那么即使 attention 与 lm_head 走确定性路径，logprob 依然不可复现。</p>\n<p>系统代价上，这条共存路径的成本是双份的：确定性内核已经放弃了 split-K 带来的并行度，量化路径又要求额外的校验与回退分支——对不一致样本按阈值标记并回退到高精度路径重算。回退分支在长序列 attention 下的延迟尖峰尤其明显，因为它把一段本已压缩的算力重新拉回高精度。工程上的做法是把回退率作为监控指标：若回退率长期偏高，说明确定性归约与量化 scale 的交互没有被正确适配，此时继续压榨量化位宽只会放大 $\\epsilon_{\\text{quant}}$，应先修归约再谈精度。</p>\n<p>一个具体例子：decode 阶段每个 step 都要算 lm_head 与 softmax 得到 logprob，若 lm_head 的 GEMM 在 NVFP4 下按 batch 动态选择 split-K 因子，则同一 token 在不同 batch size 下概率不同；把该 GEMM 的 split-K 因子钉死、softmax 用确定性 reduce 树后，采样记录与训练侧重算才对齐。这里固定的是因子而非精度，两者正交。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-49\">四十九 · 与异步流水线的分工</h3>\n<p>异步 Rollout 流水线与批不变内核常被同时部署，但职责必须分清。异步流水线通过重叠预填与解码、错峰权重同步来提升吞吐，代价是 rollout 引擎持有的策略版本落后，产生 staleness；批不变内核不解决 staleness，它只保证“在同一版本策略下，同一 prompt 在任何 batch 组成中采样出相同概率”。两者叠加时的正确分工是：批不变内核负责把 $\\epsilon_{\\text{det}}$ 压到可忽略，使重要性比率校正只需处理 $\\epsilon_{\\text{stale}}$；若 $\\epsilon_{\\text{det}}$ 未压下去，staleness 校正公式里的比率会被数值噪声污染，校正本身失去意义。</p>\n<p>调度层面的收益是连锁的。批不变内核让批调度器在组批时不再需要为数值一致性做特殊排序，可自由追求吞吐——这一点对异步流水线尤其关键，因为异步调度恰恰依赖灵活的组批来填满流水线气泡。反过来，若调度器仍被迫按固定批形状组批，异步流水线的吞吐优势就被抵消。系统代价上，固定归约顺序使 kernel 性能相对 stock 实现有可测损失，长序列 attention 下尤为明显；异步流水线若本身吞吐预算紧张，这笔损失会直接体现在端到端 token 吞吐上，需要与 staleness 校正带来的样本利用率提升做净额比较。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-50\">五十 · 适用条件与规模上限的判定</h3>\n<p>把适用条件写成可执行的判定序列，比罗列优缺点更有用。第一步，确认训练算法是否需要 off-policy 比率校正或 GRPO 组内比较——若不需要，批不变内核的可复现性收益无从兑现，直接排除。第二步，确认偏差主导项是否为归约顺序：固定 batch size 复测方差是否收敛，是则进入候选。第三步，确认吞吐预算能否承受固定 split-K 的损失：长序列 attention 占比高的负载，损失最重；短序列、大批量 decode 的负载，损失相对可控。第四步，确认框架版本对齐能力：确定性路径需与训练侧 kernel 版本严格对齐，框架升级时需同步验证，若团队没有这条验证链路，定制内核会在升级后静默失效，归约顺序重新随 batch 变化。</p>\n<p>规模上限来自定制成本。批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线适配，适配不完整时可能出现归约顺序仍随 batch 变化——这是最隐蔽的失败模式，因为表面配置已固定，实际流水线里的异步拷贝仍可能引入批相关次序。因此适配完成后必须做逐位一致性验证，而不是只测吞吐。对中小规模 RL 任务，若组内比较的噪声尚在容忍范围，把工程预算投向异步流水线或投机采样往往回报更高；批不变内核的性价比拐点出现在“ratio 频繁越界导致裁剪失效、样本被大量丢弃”的场景，此时可复现性直接转化为有效样本率。</p>\n<p>最终判断落在一条工程规则上：先测偏差分解，再选算法列；$\\epsilon_{\\text{det}}$ 主导则固定归约顺序与分块策略，$\\epsilon_{\\text{quant}}$ 主导则先修量化内核的确定性再谈位宽，$\\epsilon_{\\text{stale}}$ 主导则调流水线节奏并用比率校正兜底。三者同时显著时，按定制成本从低到高排序实施，把逐位一致性验证作为每次框架升级的回归项，而不是一次性配置。</p>\n\n<h3 id=\"alg-batch-invariant-rollout-sec-51\">五十一 · 选型边界：批不变内核与量化稳定、异步同步、stock 内核的分工</h3>\n<p>把批不变 Rollout 采样放回同族算法谱系里看，它处理的既不是量化误差也不是权重陈旧，而是<b>归约顺序随 batch 组成漂移</b>这一确定性内核层面的问题。NVFP4 量化稳定针对的是低精度表示带来的分布偏移，异步权重同步针对的是 rollout 与训练之间的 staleness，二者都在“概率值本身有偏”这一层做补偿；批不变内核则把同一 token 的 logprob 钉死为逐位可复现，使重要性比率落在 $e^{\\Delta}\\in[1-\\epsilon,1+\\epsilon]$ 的窄带内，PPO/GRPO 的裁剪阈值不会被数值噪声误触发。因此选型的第一个判据是<b>噪声来源</b>：若组内比较的方差主要来自量化，应先做量化路径的确定性验证；若来自权重版本差，应先收敛同步周期；只有当同一策略、同一动作在不同 batch 下给出不同 logprob 时，批不变内核才是对症的那一刀。三者可以叠加，但定制成本与验证负担也叠加，工程上应按噪声贡献排序逐项引入，而不是一次性全上。</p>\n<p>第二个判据是<b>吞吐预算与序列长度</b>。批不变内核固定 split-K 因子、固定 attention score 分块的 max 与 sum 归约树、禁用批相关的 split-K 变体，代价是放弃部分并行度：长序列 attention 下速度低于 stock 内核，这是可测的损失而非偶发抖动。写成约束即：固定分块与确定性归约树使 $\\mathrm{order}(\\cdot)\\perp \\mathrm{batch\\ size}$，但并行度被钉死，长序列时单步延迟上升。若 SLO 以吞吐为主且序列偏长，可复现性收益会被速度损失抵消；反之，若 SLO 明确要求 logprob 可复现、GRPO 组内归一化必须干净，则这笔损失是必要开销。决策上可先在小批动态组批场景测量 stock 内核的 logprob 抖动幅度，若抖动已接近裁剪阈值，再切换到批不变配置；若抖动远小于阈值，保留 stock 内核追求吞吐更划算。</p>\n<p>第三个判据是<b>适配完整度</b>。批不变内核需与 Blackwell 的 TMA 与 warp-specialized 流水线对齐，定制成本高；适配不完整时归约顺序仍可能随 batch 变化，此时“逐位一致”只是名义上的。与 NVFP4 量化路径的兼容更需单独验证：若量化内核未保持确定性归约，logprob 逐位一致的前提被破坏，GRPO 组内比较仍混入数值噪声。下表给出工程取舍的快速对照。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>处理的噪声源</th><th>主要系统代价</th><th>适用条件</th></tr></thead><tbody><tr><td>批不变 Rollout 采样</td><td>batch 组成与归约顺序导致的不可复现</td><td>固定 split-K 牺牲并行度，长序列吞吐下降；内核定制与版本对齐成本</td><td>需 off-policy 比率校正与 GRPO 组内比较，尤其异步 rollout 的 staleness 校正</td></tr><tr><td>NVFP4 量化稳定</td><td>量化误差导致的分布偏移</td><td>低精度路径的校准与验证开销</td><td>显存与带宽受限、可接受量化误差且已做确定性验证</td></tr><tr><td>异步权重同步</td><td>rollout 与训练间的 staleness</td><td>同步周期与吞吐的折衷</td><td>分离式预填/解码、跨节点 rollout，staleness 可控</td></tr><tr><td>stock 内核</td><td>无（不保证可复现）</td><td>无额外定制成本，吞吐最优</td><td>噪声远小于裁剪阈值，或不做组内比较</td></tr></tbody></table>\n<p>落到工程判断上：批不变内核的收益是调度器不再为数值一致性做特殊排序，可自由组批追求吞吐，这是它相对“按 batch 形状约束组批”的旧做法的结构性优势；但它的失效条件很明确——长序列 attention 下吞吐损失、TMA 与 warp-specialized 流水线适配不完整、NVFP4 量化内核未保持确定性归约。部署时应把“同一 prompt 在不同 batch size 下 logprob 逐位一致”作为验收项而非假设项，并在框架升级时同步验证训练侧与 rollout 侧 kernel 版本严格对齐；一旦这条对齐断裂，比率校正与组内归一化的前提就整体失效，此时宁可回退到高精度路径重算不一致样本，也不要在不确定的内核上继续放大批形状自由度。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · Rollout引擎与训练解耦</td></tr><tr><td>解决什么</td><td>RL训练要求同一prompt在不同批次位置采样结果一致，但GPU kernel的批大小相关归约顺序使logits随ba…</td></tr><tr><td>一句话机制</td><td>固定归约顺序与分块策略，使attention/GEMM的数值结果与batch组成无关，从而让rollout采样与训练重…</td></tr><tr><td>代价与失效</td><td>固定归约顺序放弃split-K等吞吐优化，kernel性能相对stock实现有可测损失；确定性路径需与训练侧kernel版本严格对齐，框架…</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-batch-invariant-rollout · 共 8 个片段</p>\n";break;}}})();
